  FT["PH-H9565"] = {"id":"PH-H9565","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11120_2018.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring September 2 of Every Year a Special Nonworking Holiday in the Province of Ifugao, in Commemoration of the Surrender of General Tomoyuki Yamashita, Commander of the Japanese Imperial Army in the Philippines in Kiangan Ifugao","orig":"An Act Declaring September 2 of Every Year a Special Nonworking Holiday in the Province of Ifugao, in Commemoration of the Surrender of General Tomoyuki Yamashita, Commander of the Japanese Imperial Army in the Philippines in Kiangan Ifugao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11120","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-30","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11120_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9565-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September 2 of every year is hereby declared a special nonworking holiday in the Province of Ifugao, in commemoration of the surrender of General Tomoyuki Yamashita, Commander of the Japanese Imperial Army in the Phihppines, in Kiangan, Ifugao."}},{"id":"PH-H9565-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Provincial Government of Ifugao, in coordination with the municipal government of Kiangan, the National Historical Commission of the Philippines (NHCP), the Philippine Veterans Affairs Office (PVAO) and the Military Shrines Service (MSS), shall lead appropriate and meaningful commemorative programs and activities to be participated and municipal government agencies and instrumentalities, and civic, religious, nongovernment, business and civil society organizations, in order to give significance and honor the heroes and heroines who contributed to the Philippines’ liberation from the Japanese forces."}},{"id":"PH-H9565-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"- This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
