  FT["PH-H9571"] = {"id":"PH-H9571","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11126_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring November 22 of Every Year a Special Nonworking Holiday in the Province of Sultan Kudarat in Commemoration of its Founding Anniversary","orig":"An Act Declaring November 22 of Every Year a Special Nonworking Holiday in the Province of Sultan Kudarat in Commemoration of its Founding Anniversary"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11126","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-30","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11126_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9571-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"November 22 of every year is hereby declared a special nonworking holiday in the Province of Sultan Kudarat in commemoration of its founding anniversary."}},{"id":"PH-H9571-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9572"] = {"id":"PH-H9572","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11127_2018.html","fetchedAt":"2026-10-06","articleCount":25,"structureMode":"ARTICLE","title":{"zh":null,"en":"The National Payment Systems Act","orig":"An Act Providing for the Regulation and Supervision of Payment Systems \"The National Payment Systems Act\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11127","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-10-30","completenessNote":"全文，共 25 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11127_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9572-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"- Title. - The short title of this Act shall be \"The National Payment Systems Act\"."}},{"id":"PH-H9572-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. - The State recognizes that payment systems are crucial parts of the financial infrastructure of the country and it is essential that they function safely and efficiently for the stability and effectiveness of the monetary and financial system."}},{"id":"PH-H9572-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. - The State shall promote, through the Bangko Sentral, the safe, secured, efficient and reliable operation of payment systems in order to control systemic risk and provide an environment conducive to the sustainable growth of the economy."}},{"id":"PH-H9572-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. - For the purpose of this Act, the following terms shall refer to:\n(a) Bangko Sentral – the Bangko Sentral ng Pilipinas established under Republic Act No. 7653;\n(b) Clearing – the process of transmitting, reconciling, and in some cases, confirming payment orders prior to settlement, and the establishment of final payment obligations for settlement;\n(c) Designated payment system – the payment system that has been designated as such by the Bangko Sentral pursuant to this Act and its implementing rules and regulations;\n(d) Director - any member of the board of directors of a participant to the payment system, or a person considered as such under Bangko Sentral regulations;\n(e) End-use r - any person who originally initiates the instruction to pay or the ultimate receiver of funds in a payment system;\n(f) Fund – any unit of value that forms the consideration or object of transactions;\n(g) Issuer – any person who provides the means or the instrument to hold or transfer funds;\n(h) M anager - any person of recognized competence in payment system designated by the Bangko Sentral to manage the operations of the operator of a designated payment system as provided under Section 17 hereof. For this purpose, personnel of the Bangko Sentral may be designated as manager;\n(i) M onetary Board - the Monetary Board of the Bangko Sentral;\n(j) Netting - an agreed offsetting of obligations by participants of payment systems;\n(k) Officer – any person who is an employee holding a management position in any of the participants to the payment system, or a person considered as such under Bangko Sentral regulations;\n(l) Operator – any person who provides clearing or settlement services in a payment system, or defines, prescribes, designs, controls or maintains the operational framework for the system;\n(m) Participant – the operator, issuer, service provider, or any person involved in the payment system other than the end-user;\n(n) Payment instrument - any instrument, whether tangible or intangible, that enables a person to transfer funds;\n(o) Payment order – an order or message requesting the transfer of funds to the order of the payee;\n(p) Payment system – the set of payment instruments, processes, procedures and participants that ensures the circulation of money or movement of funds;\n(q) Payment S ystem Management Body - the entity organized by participants of the designated payment system for the purpose of self-regulation;\n(r) S ervice provider - an entity that provides process arrangements, technology or infrastructure to operators of a payment system;\n(s) Settlement – an act that discharges obligations in respect of fund transfers between two (2) or more parties; and\n(t) S ystemic risk – the risk that the failure of one (1) participant in a payment system, or in financial markets generally, to meet its required obligations will cause other participants or financial institutions to be unable to meet their obligations, including settlement obligations in a payment system, when due: Provided, That, such failure could threaten the stability of the system or financial markets."}},{"id":"PH-H9572-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A uthority of the Bangko Sentral. – The Bangko Sentral shall oversee the payment systems in the Philippines and exercise supervisory and regulatory powers for the purpose of ensuring the stability and effectiveness of the monetary and financial system."}},{"id":"PH-H9572-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers of the Bangko Sentral. - In the performance of its mandate under this Act, the Bangko Sentral shall have, in addition to its powers under existing laws, the following powers:\n(a) Designate a payment system if it determines the payment system as posing or having the potential to pose a systemic risk or the designation is necessary to protect the public interest.\n(1) Any such determination by the Bangko Sentral shall be conclusive. The designation of a payment system by the Bangko Sentral shall be effective until revoked. The Bangko Sentral may revoke such designation if it finds that the designated payment system no longer poses any systemic risk or it is no longer in the public interest that the system be designated.\n(2) Should the Bangko Sentral designate a payment system, it shall require the participants of the designated payment system to comply, within a reasonable period, with the provisions of this Act and its implementing rules and regulations. The Bangko Sentral shall give due consideration to the orderly transition of the operations of the newly designated payment system to ensure that it operates in a safe, efficient and reliable manner.\n(b) Require operators of the designated payment system to secure prior authority from the Bangko Sentral.\n(1) In granting the authority, the Bangko Sentral shall take into consideration the capability of an operator in terms of its financial resources, technical expertise, and reputation. The licensing process shall include, but not be limited to, an assessment of the ownership structure, governance, key personnel, business model, risk management and financial resources.\n(2) No person or entity shall be allowed to act as an operator of a designated payment system without prior authority from the Bangko Sentral. The determination of whether a person or entity is acting as an operator of a designated payment system without Bangko Sentral authority shall be made by the Monetary Board. To resolve such issue, the Monetary Board may, through the appropriate department of the Bangko Sentral, examine, inspect or investigate the books and records of such person or entity.\n(c) Accredit or require, when deemed necessary, a payment system management body organized by participants of the designated payment system for the purpose of self-regulation.\n(1) The accredited payment system management body may issue and enforce its rules and regulations and impose appropriate sanctions among participants of the designated payment system : Provided, That, such rules and regulations shall be with prior Bangko Sentral approval and subject to its review.\n(d) Issue, through the Monetary Board, rules and regulations governing the following:\n(1) The standard of operation of payment systems and the conduct of examination of the participants of the designated payment systems, in such frequency as may be prescribed by the Monetary Board, to determine compliance with laws and regulations;\n(2) The adequacy of resources of operators of the designated payment systems to ensure that the designated payment systems have a high degree of security and operational reliability and have contingency requirements for timely completion of daily processing commitments;\n(3) The qualifications and disqualifications of individuals elected or appointed as directors or officers of operators of the designated payment systems with particular regard to their integrity, experience, education, training and competence. The Monetary Board may suspend, disqualify or remove any director or officer found unfit for the position;\n(4) The appropriate measures to ensure the confidentiality of payment information which, under the provisions of this Act and other existing laws, is considered confidential;\n(5) The necessary measures to ensure the compliance of designated payment systems with Republic Act No. 9160, as amended, otherwise known as the \"Anti-Money Laundering Act of 2001\", and other related laws;\n(6) The mechanism for the protection of the rights of the end-users and participants to the designated payment systems;\n(7) Principles on setting prices or pricing mechanisms in payment systems;\n(8) Guidelines applicable to payment system management bodies, including the grant and revocation of accreditation; and\n(9) Other pertinent matters as may be determined by the Monetary Board.\n(e) Issue, through the Monetary Board, directives and orders to any participant of a payment system whenever the Monetary Board has determined that it is necessary to ensure the safety, efficiency or reliability of a payment system or it is in the interest of the public to do so.\n(f) Require participants of payment systems to submit reports on their operations and provide information for statistical, policy development, supervisory and regulatory purposes.\n(g) Assess and collect from the participants of the designated payment systems an annual fee in such amount, as may be necessary to cover expenses related to or incidental to the conduct of supervisory functions over such entities, subject to the rules prescribed by the Monetary Board.\n(h) Such other powers as may be reasonably necessary to meet the objectives of this Act."}},{"id":"PH-H9572-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A doption of International Standards and Practices. - In the exercise of its authority under this Act, the Bangko Sentral shall be guided by internationally accepted standards and practices."}},{"id":"PH-H9572-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Bangko Sentral Authority to Own and Operate a Payment Sy stem. - The Bangko Sentral shall have the authority to own and operate payment systems as may be deemed necessary by the Monetary Board. The Bangko Sentral shall have the authority to determine who shall be allowed to participate in payment systems owned and operated by it and who shall be allowed to open an account with the Bangko Sentral for settlement purposes. The Bangko Sentral shall adopt internal safeguards to ensure appropriate independent oversight of its operator functions."}},{"id":"PH-H9572-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Coordination with Other Government Agencies and Foreign Regulators. – The Bangko Sentral shall coordinate with other regulators and other concerned government agencies to avoid gaps, inefficiencies, duplications and inconsistencies in their respective regulation of other systems which are related to or interconnected with payment systems. The grant, suspension or revocation of any government license necessary for the conduct of business of a payment system operator must be done only with prior consultation with the Bangko Sentral.\nThe Bangko Sentral shall coordinate with the Securities and Exchange Commission (SEC) to facilitate the orderly discharge of payment obligations arising from security transactions in securities trading, clearing and settlement systems under Republic Act No. 8799 or \"The Securities Regulation Code\".\nThe Bangko Sentral shall likewise coordinate with the overseers of payment systems of other countries to facilitate safe, efficient and reliable cross-border payment transactions."}},{"id":"PH-H9572-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Registration of Payment System Operators. - Within six (6) months from the effectivity of this Act, all operators of payment systems as defined under Section 4 of this Act shall register with the Bangko Sentral. Operators of payment systems, which shall commence business or operations subsequent to the effectivity of this Act, shall register with the Bangko Sentral in such manner and within such reasonable period as may be prescribed by the Monetary Board."}},{"id":"PH-H9572-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Organization of Operators of Designated Payment Sy stems. - Operators of the designated payment system, except payment systems operated by the Bangko Sentral, shall be required to incorporate as stock corporations for the purpose of operating a payment system, and shall meet the minimum requirements as may be prescribed by the Monetary Board. Operators of designated payment systems, so long as they continue to be authorized by the Bangko Sentral to operate as such, shall not be included in the definition of a debtor under Republic Act No. 10142, otherwise known as the \"Financial Rehabilitation and Insolvency Act (FRIA) of 2010\"."}},{"id":"PH-H9572-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Certificate of Authority to Register Operators of Designated Payment System. – The SEC shall not register the articles of incorporation of any operator of a designated payment system, or any amendment thereto, or otherwise issue a license to do business in the Philippines, unless accompanied by a certificate of authority to register issued by the Monetary Board, under its seal. The SEC shall also not register the by-laws of any operator of a designated payment system, or any amendment thereto, unless accompanied by a certificate of authority from the Bangko Sentral."}},{"id":"PH-H9572-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Transfer and A cquisition of Substantial Shareholdings. – No person shall acquire shares in an operator of a designated payment system that will result in ownership or control, directly or indirectly, of more than ten percent (10%) of the voting stock of such operator, without obtaining the prior approval of the Monetary Board. Prior to Monetary Board approval, no such transfer or acquisition of shares shall have legal effect nor shall the same be recognized in the stock and transfer books of the operator or in the records of any government agency."}},{"id":"PH-H9572-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Responsibilities of the Operator of the Designated Payment System. – The operator of the designated payment system shall be primarily responsible for the maintenance and operation of a safe, efficient and reliable payment system in accordance with rules and regulations. This includes the development of a process, which shall be subject to Bangko Sentral review, for the selection, monitoring and self-regulation."}},{"id":"PH-H9572-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Finality of Settlement. - Notwithstanding the provisions of existing laws to the contrary, settlement effected in accordance with the agreed procedures of a payment system shall be final and irrevocable and shall not be subject to reversal for any reason whatsoever: Provided, That, if it is shown and established that any such fund so paid and transferred was not legally due, the settlement shall remain and such amount shall constitute a new monetary obligation owed by the payee to the person who caused the payment."}},{"id":"PH-H9572-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Notification in Case of Insolvency of Participant in a Payment System. - The participant of a payment system shall notify in writing the operator of such payment system upon the issuance of a stay order or the declaration of insolvency, bankruptcy, rehabilitation or placement under receivership or liquidation of the participant on the day of the receipt of the order or resolution issued by the court or quasi-judicial agency. Upon receipt by the operator of such notice, the operator shall immediately stop the processing of any pending payment order involving said participant.\nThe operator of a payment system shall notify in writing its participants and the Bangko Sentral upon the issuance of a stay order or the declaration of its insolvency, bankruptcy, rehabilitation or placement under liquidation on the day of the receipt of the order or resolution issued by the court or quasi-judicial agency."}},{"id":"PH-H9572-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Designation of a Manager to Manage the Operations of the Operator of a Designated Payment Sy stem. - In order to avert disruptions in payment systems which may adversely affect the country's monetary and financial stability, the Bangko Sentral may, upon determination of the existence of any of the circumstances enumerated below, based on the report of the head of the supervising or examining department, and with prior approval of the Monetary Board, designate without need for prior hearing a manager of recognized competence in payment systems to manage the operations of the operator of a designated payment system, as may be necessary or expedient.\nA threat to the safety, efficiency and reliability of the designated payment system exists as a result of any of the following:\n(a) The violation of existing laws, rules and regulations by the operator;\n(b) The failure of the operator to comply with any order of the Monetary Board;\n(c) The assets of the operator are not sufficient to give adequate protection to its participants or end-users; (d) The capital of the operator has reached a level or is eroding in a manner that may detrimentally affect its participants, users or the public in general; or\n(e) Any other financial or business condition of the operator which may be considered by the Monetary Board to be prejudicial to the interests of its participants, users or the public in general.\nThe actions of the Monetary Board taken under this section shall be final and executory, and may not be restrained or set aside by the court except on petition for certiorari on the ground that the action taken was in excess of jurisdiction or with such grave abuse of discretion as to amount to lack or excess of jurisdiction. The petition for certiorari may only be filed by the stockholders of record representing the majority of the capital stock within ten (10) days from receipt by the board of directors of the operator of the designated payment system of the notice from the Bangko Sentral advising of the designation of a manager to manage the operations of such operator.\nThe designation of a manager who will manage the operations of the operator of a designated payment system shall only be for such period during which any of therefore mentioned circumstances exists. The Monetary Board, however, may replace the manager as it may deem necessary. The manager so designated shall immediately control, manage, and administer the operations of the operator of a designated payment system. Effective immediately upon designation, the powers, functions, and duties, as well as allowances, remunerations and perquisites of the incumbent directors shall be suspended. The suspension shall also apply to the officers of such operator of a designated payment system, unless the manager gives its approval in writing for any officer to continue acting as such under such terms and conditions as the manager may determine. The relevant provisions of the articles of incorporation and by-laws of such operator are likewise suspended.\nThe manager so designated shall determine within the period prescribed by the Monetary Board, but not to exceed one (1) year from the designation, whether any of the aforementioned circumstances still exists or whether the operator of a designated payment system may be permitted to resume management with safety to its payment system participants and end-users : Provided, That any determination for the resumption of management of the operator of a designated payment system shall be subject to prior approval of the Monetary Board.\nIf the manager so designated determines that the operator of a designated payment system cannot continue its operation without causing damage to its participants, end-users or the public in general, the manager so designated shall notify the Monetary Board in writing of its findings and recommend the revocation of the certificate of authority of an operator of a designated payment system. Once the certificate of authority is revoked by the Monetary Board, the provisions of Republic Act No. 10142 shall apply. For this purpose, the Bangko Sentral may initiate the appropriate action under the aforesaid law.\nThe costs and expenses in managing the operations of the operator of a designated payment system, including the remuneration of the designated manager, shall be paid first before other claims out of the funds and properties of the operator of a designated payment system.\nThe Monetary Board shall issue implementing guidelines to govern the management of the operations of the operator of a designated payment system by the designated manager, including but not limited to:\n(a) The responsibilities of the designated manager;\n(b) The information required to be given by the operator, its directors and officers to the designated manager to facilitate the management of the operations of the operator;\n(c) The circumstances, terms, and conditions when the assets of the operator may be sold or disposed of; and\n(d) Other matters related to the effective management of the operations of the operator and the appropriate performance of the duties of the designated manager to manage the operations of the operator."}},{"id":"PH-H9572-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"N etting. - Notwithstanding the provisions of existing laws to the contrary, when an operator receives from the participant a notice pursuant to Section 16, the operator may effect the netting of all payment orders received before such notice in accordance with the (agreed procedures of the payment system. The insolvency, bankruptcy, rehabilitation, receivership or liquidation proceedings shall recognize any such netting as valid."}},{"id":"PH-H9572-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"A dministrative Sanctions. -\n(a) Without prejudice to the penalties and sanctions provided in Section 20 of this Act, the Monetary Board may, at its discretion, impose upon any participant of a designated payment system, its directors and officers, including any person or entity determined by the Monetary Board to be acting as an operator without the requisite authority from the Bangko Sentral, for violations of this Act or rules and regulations issued by the Monetary Board or any order or instruction of the Governor of the Bangko Sentral, fines in amounts as may be determined by the Monetary Board to be appropriate, but not to exceed One million pesos (P1,000,000.00) for each transactional violation or One hundred thousand pesos (P100,000.00) a day for each continuing violation, depending on the nature and gravity of the violation or irregularity: Provided, That, in case profit is gained or loss is avoided as a result of the violation, an additional fine of no less than the profit gained or loss avoided but no more than three (3) times the profit gained or loss avoided may be imposed.\n(b) The Monetary Board may suspend, disqualify, or remove any of the directors or officers of the operator of a designated payment system, in any of the following instances:\n(1) Willful violation of the charter or by-laws of the operator of the designated payment system;\n(2) Willful delay in the submission of reports of publications thereof as required by the rules and regulations to be issued by the Monetary Board pursuant to this Act;\n(3) Refusal to permit examination into the affairs of the operator of the designated payment system;\n(4) Willful making of a false or misleading statement to the Monetary Board or Bangko Sentral examiners; (5) Willful failure or refusal to comply with any provision of this Act, rule or regulation or any order instruction issued by the Monetary Board pursuant to this Act, or any order or instruction of the Governor of the Bangko Sentral; and\n(6) Willful commission of irregularities or the conduct of business that threatens the safety, efficiency or reliability of a payment system as may be determined by the Monetary Board.\nThe suspension of directors and officers of the operator of a designated payment system shall not be more than one (1) year, depending on the nature and gravity of the violation or irregularity. Resignation or termination from office shall not exempt such director or officer from administrative or criminal sanctions.\n(c) Notwithstanding the institution or pendency of an administrative proceeding, if the participant of a designated payment system and its directors and its officers concerned continue with or otherwise persist in the commission of the cited practice or violation, the Bangko Sentral may issue an order requiring such participant and its directors and officers concerned to cease and desist from the cited practice or violation, and may further order that immediate action be taken to correct the conditions resulting from such practice or violation. The cease and desist order shall be immediately effective upon service on the respondents.\n(d) The revocation of the certificate of authority of an operator of a designated payment system may be ordered by the Monetary Board on the following grounds:\n(1) The operator committed a violation of or has not complied with the provisions of this Act or the rules and regulations on orders and instructions issued by the Monetary Board or any order or instruction of the Governor of the Bangko Sentral, involving acts or violations which amount to fraud or expose its participants or the public to material loss or damage; or\n(2) The operator committed a violation of or has not complied with the provisions of this Act or the rules and regulations or orders and instructions issued by the Monetary Board or any order or instruction of the Governor of the Bangko Sentral, or failed to implement the rules of the payment system or a cease and desist order issued by the Bangko Sentral, and such violation or failure has been determined by the Monetary Board to be a threat to the safety, efficiency or reliability of the payment system or poses a risk to the stability of the monetary and financial system.\n(e) The cancellation of the registration of any operator of a payment system may be ordered by the Monetary Board, if it finds that the payment system operates to facilitate fraud and other transactions contrary to law, good morals and public policy.\nThe Monetary Board may also order the suspension or revocation of the certificate of authority or the registration with the Bangko Sentral of an operator of a payment system on the basis of the suspension or revocation of its permits or licenses issued by other government agencies."}},{"id":"PH-H9572-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Other Penalties and Sanctions. - Whenever any person or entity willfully violates this Act, rule or regulation, directives or orders duly promulgated by the Monetary Board pursuant hereto, the person or persons responsible for such violation shall be punished by a fine of not less than Two hundred thousand pesos (P200,000.00) or more than Two million pesos (P2,000,000.00) or by imprisonment of not less than two (2) years nor more than ten (10) years, or both, at the discretion of the court."}},{"id":"PH-H9572-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Implementing Rules and Regulations. - Within sixty (60) days from the effectivity of this Act, the Bangko Sentral ng Pilipinas (BSP) shall promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9572-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"S eparability Clause. - Should any provision herein be declared unconstitutional, the same shall not affect the validity of the other provisions of this Act."}},{"id":"PH-H9572-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Repealing Clause. – All laws, decrees, orders, rules, and regulations or other issuances or parts inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H9572-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Transitory Provision. - Payment systems existing on the day of the effectivity of this Act shall be given sufficient time, as may be determined by the Bangko Sentral, to comply with the requirements of this Act."}},{"id":"PH-H9572-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days following its publication in the Official Gazette or in two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p136"};
  FT["PH-H9573"] = {"id":"PH-H9573","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11128_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Cadiz市","en":"An Act Declaring July 4 of Every Year a Special Nonworking Holiday in the City of Cadiz, Province of Negros Occidental, in Commemoration of its Charter Day Anniversary","orig":"An Act Declaring July 4 of Every Year a Special Nonworking Holiday in the City of Cadiz, Province of Negros Occidental, in Commemoration of its Charter Day Anniversary"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11128","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11128_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9573-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July 4 of every year is hereby declared a special nonworking holiday in the City of Cadiz, Province of Negros Occidental, in commemoration of its charter day anniversary."}},{"id":"PH-H9573-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9574"] = {"id":"PH-H9574","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11129_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Araw ng El Salvador","orig":"An Act Declaring June 27 of Every Year a Special Nonworking Holiday in the City of El Salvador, Province of Misamis Oriental, in Commemoration of its Charter Day Anniversary, to Be Known as \"Araw ng El Salvador\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11129","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11129_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9574-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"June 27 of every year is hereby declared a special nonworking holiday in the City of El Salvador, Province of Misamis Oriental, in commemoration of its charter day anniversary, to be known as \"Araw ng El Salvador\"."}},{"id":"PH-H9574-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9575"] = {"id":"PH-H9575","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11130_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Padre Garcia市","en":"Kabakahan Festival","orig":"An Act Declaring December 1 of Every Year a Special Nonworking Holiday in the Municipality of Padre Garcia, Province of Batangas, in Commemoration of its Founding Anniversary and the Annual \"Kabakahan Festival\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11130","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11130_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9575-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"December 1 of every year is hereby declared a special nonworking holiday in the Municipality of Padre Garcia, Province of Batangas, in commemoration of its founding anniversary and the annual \"Kabakahan Festival\"."}},{"id":"PH-H9575-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9576"] = {"id":"PH-H9576","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11131_2018.html","fetchedAt":"2026-10-06","articleCount":44,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating the Board of Examiners for Criminologists in the Philippines","orig":"An Act Regulating the Practice of Criminology Profession in the Philippines, and Appropriating Funds Therefor, Repealing for the Purpose Republic Act 6506, Otherwise Known as \"An Act Creating the Board of Examiners for Criminologists in the Philippines\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11131","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-08","completenessNote":"全文，共 44 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11131_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9576-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title. - This Act shall be known as \"The Philippine Criminology Profession Act of 2018\"."}},{"id":"PH-H9576-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Statement of Policy. - The State recognizes the importance of criminology profession in national security, public safety, peace and order, and in nation-building and development. Hence, it shall develop and nurture competent, virtuous, productive and well-rounded criminologists whose standards of professional practice and service shall be excellent, qualitative, world-class and globally competitive through sacred, honest, effective and credible licensure examinations, coupled with programs and activities that would promote professional growth and development."}},{"id":"PH-H9576-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. - This Act shall govern:\n(a) The examination, registration and licensure for criminologists;\n(b) The supervision, control and regulation of the practice of criminology;\n(c) The standardization and regulation of criminology education;\n(d) The development of the professional competence of criminologists through Continuing Professional Development (CPD); and\n(e) The integration of all criminology professional groups, and membership of all registered criminologists to the accredited professional organization."}},{"id":"PH-H9576-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Definition of Terms. - As used in this Act, the following terms shall be defined as follows:\n(a) APO refers to the Accredited Professional Organization of criminologists, that the Professional Regulatory Board of Criminology created hereunder and, hereinafter referred to as the Board, as the one and only recognized and accredited integrated national organization of criminologists, subject to the approval of the Professional Regulation Commission (PRC) hereinafter referred to as the Commission created under Republic Act No. 8981, otherwise known as the \"PRC Modernization Act of 2000\";\n(b) Board refers to the Professional Regulatory Board for Criminologists created hereunder;\n(c) CHED refers to the Commission on Higher Education (CHED) created under Republic Act No. 7722, otherwise known as \"Higher Education Act of 1994\", in the formulation of policy standards, and monitoring of the criminology education in the country, which shall be assisted by the Criminology Technical Panel composed of the president of the APO, Chairperson of the Board of Criminology, one (1) from the academe, and two (2) from the law enforcement agencies;\n(d) Commission refers to Professional Regulation Commission (PRC) hereinafter referred to as the Commission created under Republic Act No. 8981, otherwise known as the \"PRC Modernization Act of 2000\";\n(e) Criminology refers to the scientific study of crimes, criminals, and victims, it also deals with the prevention, and solution of crimes;\n(f) Profession refers to the art and science in the practice of criminology discipline; and ,\n(g) Registered criminologist refers to a natural person who holds a valid certificate of registration and an updated professional identification card as criminologist issued by the Board and the Commission pursuant to this Act."}},{"id":"PH-H9576-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Scope of Practice. - The practice of criminology shall include, but shall not be limited to, acts or activities performed:\n(a) In line with the practice of profession or occupation as a law enforcement administrator, executive, adviser, consultant, officer, investigator, agent or employee in any private or government agencies performing law enforcement and quasi-police functions at the Philippine National Police (PNP), the National Bureau of Investigation (NBI), the Philippine Drug Enforcement Agency (PDEA), the Bureau of Fire Protection (BFP), the Bureau of Jail Management and Penology (BJMP), the Provincial Jail, the Bureau of Corrections (BUCOR), the Probation and Parole Administration (PPA), the Bureau of Internal Revenue (BIR), the Bureau of Customs (BoC), the Bangko Sentral ng Pilipinas (BSP), other government and private banks, the Philippine Postal Corporation (PPC), the Sea and Air Marshalls, the VIP Security, Airport and Seaport Police, the National Intelligence Coordinating Agency (NICA), the Intelligence Service of the Armed Forces of the Philippines (ISAFP), and other intelligence service or agencies of the government exercising similar functions;\n(b) In line with the practice of teaching profession such as those performed by a professor, instructor or teacher in any university, college or school duly recognized by the government of any of the following professional and component subjects of the criminology program: (1) Criminal Jurisprudence and Procedure; (2) Criminalistics; (3) Law Enforcement Administration; (4) Crime Detection and Investigation; (5) Correctional Administration; and (6) Criminal Sociology and Ethics, and other technical and specialized subjects in the criminology curriculum provided by the CHED;\n(c) As a technician, examiner/criminalist, or specialist in dactyloscopy, questioned document, deoxyribonucleic acid (DNA), lie detection, firearms identification, forensic photography, forensic chemistry and other scientific crime detection and investigation;\n(d) As a correctional administrator, executive, supervisor, or officer in any rehabilitation, correctional, and penal institution or facility, and in any community-based corrections, and rehabilitation agencies and/or programs;\n(e) As a counsellor, consultant, adviser or researcher in any government or private agency on any aspect of criminological research or project involving the causes of crime, children in conflict with the law, treatment of offenders, police operations, law enforcement administration, scientific criminal investigation or public safety and national security administration; and\n(f) As a private investigator, administrator, consultant or agent, or detective in any private security and investigation agency organized under the laws of the Philippines.\nThe Board, in consultation with the APO and the academe, subject to the approval of the Commission, may revise, exclude from or add to the above enumerated acts or activities as the need arises to conform with the latest trends in the practice of criminology in the country.\nPROFESSIONAL REGULATORY BOARD FOR CRIMINOLOGISTS"}},{"id":"PH-H9576-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Creation, and Composition of the Professional Regulatory Board for Criminologists. - There is hereby created a Professional Regulatory Board for Criminologists, a collegial body under the administrative supervision and control of the Commission, to be composed of a Chairperson and four (4) members appointed by the President of the Philippines from a list of three (3) recommendees for each position, chosen and ranked by the Commission from a list of three (3) nominees for every position endorsed by the APO. The new Board shall be organized not later than six (6) months from the effectivity of this Act."}},{"id":"PH-H9576-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Qualifications of the Chairperson and Members of the Board. - The Chairperson and each member shall, at the time of their appointment, possess all these qualifications:\n(a) Must be a natural-born Filipino citizen and a resident of the Philippines;\n(b) Must be of good moral character, good reputation and of sound mind and body;\n(c) Not convicted by a court of competent jurisdiction of any offense involving moral turpitude;\n(d) Must be a graduate of Bachelor of Science in Criminology, and a holder of a Post-Graduate Degree in Criminology or a lawyer in any reputable school recognized by the CHED;\n(e) Must be a registered criminologist with a valid certificate of registration and a valid professional identification card, having at least ten (10) years of practice in the profession prior to the appointment including no less than two (2) years teaching experience of criminology or law subjects in full-time or part-time capacity in the college of criminology or college of law recognized by the government through the CHED;\n(f) Must be a member in good standing of the APO but not an officer or trustee thereof; and\n(g) Must not be a member of the faculty of any school, college or university where a regular class or review course in criminology is offered, nor a member of the staff of reviewers in a review school or center, and must not have any direct or indirect pecuniary interest in any such institution."}},{"id":"PH-H9576-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Term of Office. - The Chairperson and members of the Board shall hold office for a term of three (3) years from the date of appointment or until their successors shall have been qualified and appointed. They may be reappointed to the same office for another term of three (3) years immediately after the expiry of their term: Provided, That the holding of such position shall not be more than two (2) terms nor more than six (6) years, whichever is longer: Provided, further, That the first Board under this Act shall hold these terms of office: the Chairperson for three (3) years, the first two (2) members for two (2) years, and the second two (2) members for one (1) year: Provided, finally, That any appointee to a vacancy with an unexpired period shall only serve such period. The Chairperson and the members shall duly take their oath of office."}},{"id":"PH-H9576-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Compensation, Allowances and Other Benefits. - The Chairperson and members of the Board shall receive compensation, allowances and other benefits comparable to that being received by the Chairpersons and members of other Professional Regulatory Boards under the Commission as provided for under Section 10 of Republic Act No. 8981 and other existing laws."}},{"id":"PH-H9576-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Powers, Functions, Duties and Responsibilities of the Board. - The Board shall exercise executive, administrative, rule-making and quasi-judicial powers in carrying out the provisions of this Act. It shall be vested with the following specific powers, functions, duties and responsibilities:\n(a) To administer, supervise, and monitor the conduct of the licensure examination, registration, membership in the APO and the practice of criminology in accordance with the provisions of this Act;\n(b) To receive complaints and decide the matter as to the malpractices and unethical conduct in the practice of the criminology profession;\n(c) To promulgate and issue rules and regulations implementing the provisions of this Act;\n(d) To promulgate and adopt Code of Ethics and Code of Good Governance for the practice of criminology;\n(e) To adopt an official seal of the Board;\n(f) To prescribe and promulgate guidelines on the conduct of a CPD program for criminologists in consultation with the APO;\n(g) To promulgate, adopt or amend the syllabi and tables of specifications of the subjects for the licensure examination/s in consultation with the APO, the academe, and the CHED Technical Panel for Criminology, prepare questions for the licensure examination which shall strictly be within the scope of the syllabi of the subjects for examination, as well as administer and correct, and release the results of the licensure examinations;\n(h) To issue, suspend, revoke or reinstate the certificate of registration of the registered criminologist or cancel temporary/special permit granted to foreign criminologist;\n(i) To administer oaths in the performance of its functions such as, but not limited to, the oath of a professional to successful examinees in licensure examination for criminologist together with the APO in an appropriate mass oath-taking ceremony to be held for the purpose;\n(j) To monitor the conditions affecting the practice of criminology and whenever necessary, adopt such measure as may be deemed proper for the enhancement of the profession and the maintenance of high professional, ethical an^ technical standards; for this purpose, the members of the Board, duly authorized by the Commission, may conduct ocular inspection of establishments where criminology is practiced, and recommend sanction as it may deem proper to the appropriate government agency concerned;\n(k) To monitor all colleges and universities offering criminology program and recommend sanctions to the CHED or to other authorized government offices, for noncompliance with the policies, standards, and requirements as to faculty qualifications, laboratory, library, facilities and equipment, research outputs, curriculum and administration of the criminology education;\n(l) To hear and investigate cases on violations of this Act, its implementing rules and regulations (IRR), the Code of Ethics, the Code of Good Governance and other policies, and for this purpose, to issue summons, subpoena ad testificandum and subpoena duces tecum to alleged violators and/or witnesses to compel their attendance in such hearings or investigations and the production of documents in connection therewith:\n(m) To delegate to the Commission the hearing or investigation of cases against the alleged violators: Provided, That the hearing or investigation of cases wherein the issue or question involved strictly concerns the technical practice of criminology shall be presided over by at least one (1) member of the Board assisted by a Legal or Hearing Officer of the Commission;\n(n) To recommend to the Commission the endorsement of cases involving criminal violations of this Act, its IRR, and other laws to the Prosecution Office or appropriate government agency, for investigation and appropriate action;\n(o) To disqualify applicants for the licensure examination who has been previously convicted of a crime with finality involving moral turpitude. Hear and decide administrative cases against the examinees or registered criminologists if they have been convicted of a crime involving moral turpitude: Provided, That if they are found guilty, the Board shall cancel their examination papers and/or preclude them from taking another licensure examination, or to revoke/suspend their certificates of registration and cause the surrender of their professional identification card subject to the rules and regulations of the PRC: Provided, further, That the decision of the Board shall, unless appealed to the Commission, become final and executory after fifteen (15) days from receipt of notice of judgment or decision;\n(p) To conduct, through the Legal or Hearing Officers, summary proceedings against the examinees who commit violations of this Act, its IRR, any of the Codes aforementioned, including violation of the General Instructions to Examinees, and to render summary judgment thereon which shall, unless appealed to the Commission, become final and executory after fifteen (15) days from receipt of notice of judgment or decision;\n(q) To prepare an annual report of accomplishments on programs, projects and activities of the Board for submission to the Commission after the close of each calendar year and make appropriate recommendations to the Commission on issues or problems affecting the criminology profession; and\n(r) To exercise such other powers as may be provided by law as well as those which may be implied from, or which are incidental or necessary to the effective carrying out of the express powers granted to the Board to achieve the objectives and purposes of this Act. The resolutions, rules and regulations and other policies issued and promulgated by the Board shall be subject for review and approval by the Commission.\nHowever, the Board's decisions, resolutions or orders rendered in an administrative case shall be subject to review only if on appeal."}},{"id":"PH-H9576-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Grounds for Removal or Suspension of Board Chairperson/Member. - The President of the Philippines, upon the recommendation of the Commission, after due process and administrative investigation conducted by the Commission, may remove or suspend the Chairperson or member of the Board on any of the following grounds:\n(a) Gross neglect, incompetence or dishonesty in the discharge of one's duty;\n(b) Commission of any of the causes/grounds and the prohibited acts provided in this Act and the offenses in the Revised Penal Code, the Anti-Graft and Corrupt Practices Act, and other laws;\n(c) Manipulation or rigging of the results in the licensure examination for criminologists, disclosure of secret and confidential information on the examination questions prior to the conduct thereof, or tampering of grades; and\n(d) Conviction with final judgment of any crime involving moral turpitude. The Commission, in the conduct of the investigation, shall be guided by Section 7(s) of Republic Act No. 8981, the rules on administrative investigation, and the applicable provisions of the New Rules of Court."}},{"id":"PH-H9576-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Administrative Supervision of the Board; Provision of Support Services. - The Board shall be under the administrative supervision of the Commission. The Commission shall keep all records of the Board including applications for examination, examination papers and results, minutes of deliberation and administrative cases. The Commission shall designate the Secretary of the Board and shall provide the other support services to the Board in order to implement the provisions of this Act.\nEXAMINATION, REGISTRATION, CERTIFICATION AND LICENSURE"}},{"id":"PH-H9576-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Passing of Licensure Examination Requirements. - Except as otherwise specifically allowed under this Act, applicants for registration for the practice of criminology shall be required to pass a licensure examination as provided for in this Act, in such places and dates as the Commission may designate in the resolution thereof on the Master Schedules for all licensure examinations in accordance with Section 7(d) of Republic Act No. 8981."}},{"id":"PH-H9576-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications of an Applicant for the Licensure Examination. - An applicant for the licensure examination for criminologist shall satisfactorily prove that one possesses the following qualifications:\n(a) Must be a citizen of the Philippines or a foreign citizen whose country/state has reciprocity with the Philippines in the practice of criminology;\n(b) Must be of good moral character, good reputation and of sound mind and body certified by the school wrhere he/she graduated and the barangay where he/she lives, unless the examinee is a foreign national a certification from any professional of good standing will do;\n(c) Must hold a bachelor's degree in criminology duly accredited by the CHET) and conferred by a school/college/university duly authorized by the government or its equivalent degree obtained by either a Filipino or foreign citizen from an institution of learning in a foreign country/state: Provided, That it is duly recognized and/or accredited by the CHED;\n(d) Must not have been convicted of an offense involving moral turpitude by a court of competent jurisdiction; and\n(e) Those who failed five (5) times whether consecutive or cumulative in the criminologist licensure examination, must present a certification issued by a reputable institution duly recognized by the CHED that such applicant has satisfactorily completed a refresher course in criminology."}},{"id":"PH-H9576-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Subjects for Licensure Examination. - The licensure examination for criminologists shall include, but shall not be limited to, the following:\nSubjects Relative Weights (a) Criminal Jurisprudence and Procedure:\nCriminal Law (Book I); Criminal Law (Book II); Related Special Penal Laws;\nCriminal Procedure;\nEvidence;\nCourt Testimony 20% (b) Law Enforcement Administration:\nPolice Organization and Administration, Police Planning;\nPolice Patrol Operations, Police Communication System;\nPolice Intelligence;\nPolice Personnel and Records Management; Comparative Police Systems;\nIndustrial Security Management 20% (c) Crime Detection and Investigation:\nFundamentals of Criminal Investigation;\nSpecial Crime, Organized Crime Investigation; Fire Technology and Arson Investigation;\nTraffic Management and Accident Investigation;\nDrug Education and Investigation;\nVice Control 15% (d) Criminalistics:\nForensic Photography; Personal Identification; Forensic Medicine; Polygraphy; Examination; Forensic Ballistics;\nQuestioned Documents 20% (e) Correctional Administration:\nInstitutional Corrections; Non-Institutional Corrections 10% (f) Criminal Sociology:\nIntroduction to Criminology and Psychology of Crimes;\nPhilippine Criminal Justice System;\nEthics and Values;\nJuvenile Delinquency and Crime Prevention;\nHuman Behavior and Crisis Management; Criminological Research and Statistics 15% The Board, in consultation with the APO and the academe and subject to the approval of the Commission, may revise or exclude any of the subjects with their corresponding ratings and their syllabi, and add new ones as the need arises to conform with technological changes brought about by developing trends in the profession.\nHowever, the Board may change or revise any of the above subjects in the event the CHED shall correspondingly change the curriculum prescribed for the Degree of Bachelor of Science in Criminology. In the conduct of the examination, the Board, in its discretion, may give practical and field examinations in each subject, as it may deem fit."}},{"id":"PH-H9576-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Persons to Teach Subjects for Licensure Examination. - All subjects for the licensure examination shall be taught by a registered criminologist who is a holder of a valid certificate of registration and updated professional identification card for criminologist, APO membership, and CPD required units earned, and meet other CHED requirements. Allied fields in criminology may also be allowed to teach as it may deem proper."}},{"id":"PH-H9576-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Rating in the Licensure Examination. - To pass the licensure examination for criminologist, a candidate must obtain a weighted average rating of seventy-five percent (75%) with no grade less than sixty percent (60%) in any given subject. In case the examinee obtains a weighted average rating of seventy-five percent (75%) but, has a grade below sixty percent (60%) in any of the subjects, the result of the examinee shall be deferred, and be required to retake that particular subject/s. The deferred examinee shall only be allowed to retake once within two (2) years from the date of the examination, and shall be required to obtain a grade not lower than eighty percent (80%) on the subject, to be considered to have passed the licensure examination. If the examinee failed to retake after the lapse of two (2) years or failed to get the passing mark of eighty percent (80%), the examinee shall retake all the board subjects.\nAny examinee who failed three (3) or more board subjects shall be deemed to have failed the board examination."}},{"id":"PH-H9576-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Report of Rating. - The Board shall submit to the Commission the ratings obtained by the candidates not later than ten (10) days after the last day of the examination, unless the period is extended for a valid cause."}},{"id":"PH-H9576-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Oath. - All successful candidates of the licensure examination shall take their oath of profession in person before the Board or any of its members, and with the APO in an oath-taking ceremony held for such purpose. Any person authorized by law may administer oath to any successful examinees only upon membership of the APO prior to entering the practice of the profession."}},{"id":"PH-H9576-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of Certificate of Registration and Professional Identification Card. - A certificate of registration shall be issued to those who shall register, subject to payment of fees prescribed by the Commission. It shall bear the signatures of the Chairperson and the Commissioners of the Commission and the Chairperson and members of the Board, stamped with the official seal of the Commission and of the Board, certifying that the person named therein is entitled to practice the criminology profession with all the privileges appurtenant thereto. It shall remain in full force and effect until withdrawn, suspended or revoked in accordance with this Act.\nA professional identification card bearing the registration number and date, its validity, and expiry duly signed by the Chairperson of the Commission shall likewise be ^issued to every registrant who has paid the prescribed fee. It shall be reissued after every three (3) years upon payment of the prescribed fees, prescribed units earned in the CPD, and certified by the APO as active member."}},{"id":"PH-H9576-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Refusal to Issue Certificate of Registration and Professional Identification Card or Temporary/Special Permit. - The Board shall not register any successful applicant for registration who has been:\n(a) Convicted with finality of a crime involving moral turpitude by a court of competent jurisdiction;\n(b) Found guilty of immoral or dishonorable conduct by the Board;\n(c) Summarily adjudged guilty for violation of the General Instruction to Examinees by the Board; and\n(d) Declared of unsound mind by a court of competent jurisdiction. In refusing such registration, the Board' shall give the applicant a written statement setting forth the reasons thereof and shall file a copy in its records."}},{"id":"PH-H9576-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Revocation or Suspension of the Certificate of Registration and Cancellation of Temporary/Special Permit - The Board shall have the power, upon notice and hearing, to revoke or suspend the certificate of registration of a registered criminologist or to cancel a temporary/special permit granted to foreign criminologist for the commission of any of the following acts:\n(a) Violation of any provision of this Act, its IRR, the Code of Ethics, the Code of Good Governance, or policy of the Board and/or the Commission;\n(b) Conviction of a crime with finality involving moral turpitude;\n(c) Perpetration or use of fraud in obtaining one's certificate of registration, professional identification card or temporary/special permit;\n(d) Gross incompetence, negligence or ignorance resulting to death or injury of a person, or damage to property;\n(e) Nonrenewal of the professional identification card for a period of six (6) years with the PRC without justifiable cause;\n(f) Aiding or abetting the illegal practice of a non-registered criminologist by allowing the use of one's certificate of registration and/or professional identification card or temporary/special permit;\n(g) Illegally practicing the profession during the suspension from the practice thereof;\n(h) Addiction to drugs or alcohol impairing one's ability to practice the profession or a declaration by a court of competent jurisdiction that the registrant is of unsound mind; and\n(i) Noncompliance with the CPD and APO requirements, unless one is exempted therefrom, for the renewal of the professional identification card. The Board shall periodically evaluate the aforementioned grounds and revise or exclude or add new ones as the need arises subject to approval by the Commission.\nAny person, firm or association may file charge/s in accordance with the provision of this section against any registrant, and the Board may investigate the commission of any of the abovementioned causes. Affidavit-complaint shall be filed together with the affidavits of witnesses and other documentary evidence with the Board through the Legal and Investigation Office. The conduct of an investigation motu proprio shall be embodied in a formal charge to be signed by at least majority of the members of the Board. The rules on administrative investigation issued by the Commission shall govern the hearing or investigation, subject to applicable provisions of this Act, Republic Act No. 8981 and the Rules of Court."}},{"id":"PH-H9576-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reissuance of Revoked Certificate of Registration, Replacement of Lost or Damaged Certificate of Registration, Professional Identification Card or Temporary/Special Permit - The Board may, upon a verified petition, reinstate or reissue a revoked certificate of registration after two (2) years from the effectivity of the period for revocation, which is the date of surrender of the certificate and/or the professional identification card if still valid to the Board and/or the Commission. The petitioner shall prove to the Board that one has valid reason/s to practice anew the profession. In the granting of the petition, the Board shall issue a Board resolution, subject to approval by the Commissioiy A certificate of registration, professional identification card or temporary/special permit that has been declared lost may be reissued in accordance with the rules thereon and upon payment of the prescribed fees."}},{"id":"PH-H9576-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Nonpayment of the Annual Registration Fees. - The Board shall suspend a registered criminologist from the practice of the profession whether in government service, or have used the license as eligibility equivalent for promotion in government service, or in the private sector, for nonpayment of the registration fees for two (2) consecutive registration periods from the last or previous year of payment. Other surcharges shall be determined and charged by the Commission."}},{"id":"PH-H9576-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Renewal of Professional Identification Card. - The professional identification card shall be renewed only upon the completion of the prescribed minimum units of the CPD program by the registrant from the APO or any accredited provider authorized by the Commission."}},{"id":"PH-H9576-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Vested Rights; Automatic Registration. - All criminologists registered at the effectivity of this Act shall automatically be registered hereunder, subject to the provisions herein set forth as to future requirements. Certificates of registration and professional identification cards or temporary/ special permits held by such persons in good standing at such effectivity date shall have the same force and effect as though they were issued on or after the said effectivity.\nPRACTICE OF CRIMINOLOGY"}},{"id":"PH-H9576-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Lawful Practitioners of Criminology. - The following persons shall be authorized to practice the criminology profession:\n(a) Natural persons:\n(1) Duly registered criminologists and holders of valid certificates of registration and valid professional identification cards issued by the Board and the Commission pursuant to this Act; and\n(2) Holders of valid temporary/special permits issued by the Board and the Commission to foreign licensed criminologists pursuant to this Act.\n(b) Juridical persons:\n(1) Single proprietorship whose owner and technical staff are registered criminologists;\n(2) Partnership duly registered with the Securities and Exchange Commission (SEC) as professional partnership pursuant to the Civil Code and composed of partners majority of whom are registered criminologists;\n(3) Corporation duly registered with the SEC as engaged in the practice of criminology and with officers and Board of Directors who are all registered criminologists; and\n(4) Association and cooperative duly registered with the appropriate government agency as a non-stock corporation where majority of the officers, Board of Trustees and members are registered criminologists.\nThese juridical persons shall also be registered with the Board and the Commission in accordance with the rules and regulations thereon."}},{"id":"PH-H9576-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Seal, Issuance and Use of Seal. - There shall be a seal to be exclusively and legitimately used by the practitioners of the criminology profession which shall be distributed by the Board through the APO."}},{"id":"PH-H9576-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Foreign Reciprocity. - No foreigner shall be allowed to take the licensure examination for criminologists, register, receive ones certificate of registration and professional identification card, and practice criminology in the Philippines unless the requirements for the licensure examination and/or registration and practice of criminology imposed under the laws and regulations in the foreign country/state are substantially the same as those required and contemplated by the Philippine laws and regulations, and unless the foreign laws and regulations allow Philippine citizens to practice criminology within the territory of the foreign country/state on the same basis and grant the same privileges as those enjoyed by the citizens, subjects or nationals thereof."}},{"id":"PH-H9576-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Practice Through Temporary/Special Permit. - Temporary/Special permit may be issued by the Board subject to the approval by the Commission and payment of fees the latter has prescribed and charged thereof to the following:\n(a) Registered criminologists from foreign countries/states whose services are rendered either for free or for a fee:\n(1) If they are internationally known criminologists or experts in any branch, specialty or allied field of criminology; and\n(2) If their services are urgently and importantly required for lack or inadequacy of available local specialists or experts; or for the promotion or advancement of the practice of criminology through transfer of technology;\n(b) Registered criminologists from foreign countries/states whose services shall be free and limited to indigent patients in a particular hospital, center or clinic; and\n(c) Registered criminologists from foreign countries/states employed as exchange professors in a branch, specialty or allied field of criminology, in schools, colleges or universities offering the course of criminology.\nThe permit shall, among other things, contain these limitations and conditions for a period of not more than one (1) year subject to renewal: the branch or specialty of criminology and the specific place of practice such as clinic, hospital, center, school, college or university offering the course of criminology. The Board, subject to the approval of the Commission, shall promulgate rules and regulations on the implementation of this particular section."}},{"id":"PH-H9576-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Indication of Numbers: Certificate of Registration, Professional Tax Receipt and. APO Membership. - The practitioner of the criminology profession shall be required to indicate the certificate of registration number and date of issuance, the expiry of the current professional identification card, the professional tax receipt number and date, and the APO membership number and date with official receipt number and date of membership payment (annual/lifetime) on the documents one signs, uses or issues in connection with the practice of the profession."}},{"id":"PH-H9576-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Roster of Registered Criminologists. - The Board shall prepare and maintain a roster showing the names, residence and/or office address of all registered criminologists, which shall be updated annually in cooperation with the APO, indicating therein the status of the certificate of registration, professional identification card and APO membership. The roster shall be made available to any party as may be deemed necessary."}},{"id":"PH-H9576-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Integration of Registered Criminologists. - The registered criminologists shall be integrated into one (1) national organization of criminologists that is duly registered with the SEC. The Board, subject to the approval by the Commission, shall accredit the organization as the one and only integrated and accredited national organization of criminologists: Provided, That its continued accreditation is subject to compliance with the periodic requirements and standards set forth by the Commission.\nAll criminologists whose names appear in the Registry Book of Criminologists shall ipso facto or automatically become members thereof and shall receive therefrom, all the benefits and privileges upon payment of APO membership fees and dues. Membership in an affiliate organization of criminologists shall not be barred.\nPRIVILEGES OF REGISTERED CRIMINOLOGISTS"}},{"id":"PH-H9576-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Privileges of Registered Criminologists. - All registered criminologists shall be exempt from taking any other entrance or qualifying government or civil service examinations and shall be considered civil service eligible to the following government positions, among others: (1) Dactylographer; (2) Ballistician; (3) Questioned Document Examiner; (4) Forensic Photographer; (5) Polygraph Examiner; (6) Probation Officer; (7) Parole Officer; (8) Special Investigator; (9) Special Agent; (10) Investigative Agent; (11) Intelligence Agent; (12) Law Enforcement Evaluation Officer; (13) National Police Commission (NAPOLCOM) Inspector; (14) Traffic Operation Officer; (15) Associate Graft Investigation Officer; (16) Special Police Officer; (17) Safekeeping Officer; (18) Sheriff; (19) Security Officer; (20) Criminal Investigator; (21) Warden; (22) Reformation Officer; (23) Firefighter; (24) Fire Marshall; (25) Jail Officer up to the rank of Jail Superintendent; (26) Police Officer up to the rank of Police Superintendent and other law enforcement agencies, and agencies under the Criminal Justice System."}},{"id":"PH-H9576-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Preference of Appointment in Government Criminal Justice and Other Government Institutions. - Registered criminologists shall enjoy priority of appointment and shall not be required to take any qualifying or entrance examinations in the PNP, the NBI, the BJMP, the BFP, the Land Transportation Office (LTO) and other government positions related to criminology, police and law enforcement work, investigations and security, corrections and public safety of the following bureaus, departments, institutions or agencies of the government: the Department of Justice (DOJ); the Commission on Human Rights (CHR); the Office of the Ombudsman; the Philippine Ports Authority (PPA); the Commission on Elections (COMELEC); the Bureau of Treasury (BoT); the Philippine Amusement and Gaming Corporation (PAGCOR); the Department of Environment and Natural Resources (DENR); the Department of Tourism (DOT); the Department of Trade and Industry (DTI); the Armed Forces of the Philippines (AFP); the Bureau of Immigration (BI); the BoC; the Department of Transportation (DOTr); the Air Transportation Office (ATO); the Civil Aviation Authority of the Philippines (CAAP); the BSP; the BIR; the CHED; the City/Municipal Security Office; the Provincial Jail; the Provincial Security Office; the Metro Manila Development Authority (MMDA); the Supreme Court and lower courts; the Security Consultation; the Social Security System; the NAPOLCOM; the Autonomous Region in Muslim Mindanao (ARMM); the Optical Media Board; the Intellectual Property Rights Office; the PDEA; the Public Attorney's Office (PAO); the PPC; government-owned and -controlled corporations and other government agencies with positions involving the practice of criminology."}},{"id":"PH-H9576-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Lateral Entry of Registered Criminologists. - Registered criminologists who are not in the government service shall be eligible and given preference for appointment via lateral entry as Police, Fire, and Jail Inspectors or its equivalent in the PDEA, NBI, and other law enforcement agencies: Provided, That they possess the general qualifications for appointment as provided in the existing laws on appointment of Police Officers in the PNP, BJMP, BFP, PDEA, or NBI: Provided, further, That those who are already in the police, fire, and jail service as non-commissioned officers and who are already registered and licensed criminologists shall be given preference for lateral entry."}},{"id":"PH-H9576-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Penal Clause. - A fine of not less than One hundred thousand pesos (₱100,000.00) nor more than Five hundred thousand pesos (₱500,000.00), or imprisonment for not less than two (2) years and one (1) day nor more than six (6) years, or both, at the discretion of the court shall be imposed upon any person who shall commit any of the following acts:\n(a) Practicing criminology without valid certificate of registration and a valid professional identification card or a valid temporary/special permit;\n(b) Attempting to use the seal, certificate of registration and professional identification card of a registered criminologist or temporary/special permit issued to a foreign criminologist;\n(c) Abetting the illegal practice of criminology by an unregistered or unauthorized person;\n(d) Securing through false information or fraudulent means certificate of registration and professional identification card or temporary/special permit;\n(e) Impersonating a registered criminologist or a holder of a temporary/special permit; and\n(f) Violating any provision of this Act or the IRR thereof. Where the violator is a juridical person, the Board of Directors and other responsible officers of the corporation shall be held liable."}},{"id":"PH-H9576-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Enforcement. - In carrying out the provisions of this Act, the Board shall be assisted by the Commission, the APO, duly constituted government agencies and authorities and private organizations in the industry."}},{"id":"PH-H9576-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Appropriations. - The Chairperson of the PRC shall immediately include in the Commission's programs the implementation of this Act, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9576-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Transitory Provision. - The incumbent Board shall, in an interim capacity, continue to operate or function by carrying out the provisions of this Act without need of new appointments of the Chairperson and members thereof until the first Board created under this Act shall have been constituted or organized pursuant thereto."}},{"id":"PH-H9576-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Implementing Rules and Regulations (IRR). - Within ninety (90) days from the effectivity of this Act, the Board, subject to approval by the Commission, and in coordination with the APO, shall prescribe, promulgate and issue a Board Resolution on the IRR cf this Act and which shall be effective fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}},{"id":"PH-H9576-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Separability Clause. - If any provision, section or part of this Act shall be declared unconstitutional or invalid, such judgment shall not affect, invalidate or impair any other provisions, sections or parts hereof."}},{"id":"PH-H9576-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Repealing Clause. - Republic Act No. 6506, otherwise known as \"An Act Creating the Board of Examiners for Criminologists in the Philippines and for Other Purposes\", is hereby repealed. All other laws. Republic Acts, decrees, orders, letters of instruction, rules and regulations or other issuances, and parts thereof inconsistent with the provisions of this Act are likewise repealed or modified accordingly."}},{"id":"PH-H9576-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in any newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9577"] = {"id":"PH-H9577","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11132_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Fabian市","en":"An Act Declaring March 21 of Every Year a Special Nonworking Holiday in the Municipality of San Fabian, Province of Pangasinan, in Commemoration of its Founding Anniversary","orig":"An Act Declaring March 21 of Every Year a Special Nonworking Holiday in the Municipality of San Fabian, Province of Pangasinan, in Commemoration of its Founding Anniversary"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11132","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11132_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9577-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"March 21 of every year is hereby declared a special nonworking holiday in the Municipality of San Fabian, Province of Pangasinan, in commemoration of its founding anniversary."}},{"id":"PH-H9577-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9578"] = {"id":"PH-H9578","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11133_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Claveria市","en":"Araw ng Claveria","orig":"An Act Declaring July 22 of Every Year a Special Nonworking Holiday in the Municipality of Claveria, Province of Misamis Oriental, in Commemoration of its Founding Anniversary, to Be Known as \"Araw ng Claveria\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11133","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11133_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9578-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"July 22 of every year is hereby declared a special nonworking holiday in the Municipality of Claveria, Province of Misamis Oriental, in commemoration of its founding anniversary, to be known as \"Araw ng Claveria\"."}},{"id":"PH-H9578-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
