  FT["PH-H9581"] = {"id":"PH-H9581","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11136_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"Someon Ola Day","orig":"An Act Declaring September 2 of Every Year a Special Nonworking Holiday in the Province of Albay, Including the Cities Therein, in Commemoration of the Birth Anniversary of General Simeon A. Ola, to be Known as \"Someon Ola Day\"."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11136","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11136_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9581-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"September 2 of every year is hereby declared a special nonworking holiday in the Province of Albay, including the cities therein, in commemoration of the birth anniversary of General Simeon A. Ola and in recognition of his life, service and bravery, being the last Filipino army general who surrendered to the American forces during the Philippine-American war. The special holiday shall be known as the \"Simeon Ola Day\"."}},{"id":"PH-H9581-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9582"] = {"id":"PH-H9582","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11137_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Butuan市","en":"Adlaw Hong Batuan","orig":"An Act Declaring August 2 of Every Year a Special Nonworking Holiday in the City of Butuan, Province of Agusan Del Norte, in Commemoration of its Charter Day Anniversary, to Be Known as \"Adlaw Hong Batuan\"."},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11137","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11137_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9582-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"August 2 of every year is hereby declared a special nonworking holiday in the City of Butuan, Province of Agusan del Norte, in commemoration of its charter day anniversary, to be known as \"Adlaw Hong Butuan\". When the holiday falls on a Saturday or a Sunday, the special nonworking day shall be observed on the Monday that follows."}},{"id":"PH-H9582-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
