  FT["PH-H9590"] = {"id":"PH-H9590","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11145_2018.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Orani市","en":"An Act Declaring April 21 of Every Year a Special Nonworking Holiday in the Municipality of Orani, Province of Bataan, in Commemoration of its Founding Anniversary, to Be Known as Orani Foundation Day","orig":"An Act Declaring April 21 of Every Year a Special Nonworking Holiday in the Municipality of Orani, Province of Bataan, in Commemoration of its Founding Anniversary, to Be Known as Orani Foundation Day"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11145","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11145_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9590-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"April 21 of every year is hereby declared a special nonworking holiday in the Municipality of Orani, Province of Bataan, in commemoration of its founding anniversary, to be known as \"Orani Foundation Day\"."}},{"id":"PH-H9590-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9591"] = {"id":"PH-H9591","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11146_2018.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bacolod市","en":"An Act Declaring June 18 of Every Year a Special Nonworking Holiday in the City of Bacolod, Province of Negros Occidental, to Be Known as the \"Bacolod City Charter Day\", in Commemoration of the Day President Manuel L. Quezon Signed and Approved Into Effect Commonwealth Act No. 326, Creating the City of Bacolod","orig":"An Act Declaring June 18 of Every Year a Special Nonworking Holiday in the City of Bacolod, Province of Negros Occidental, to Be Known as the \"Bacolod City Charter Day\", in Commemoration of the Day President Manuel L. Quezon Signed and Approved Into Effect Commonwealth Act No. 326, Creating the City of Bacolod"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11146","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11146_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9591-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"June 18 of every year is hereby declared a special nonworking holiday in the City of Bacolod, Province of Negros Occidental, to be known as the \"Bacolod City Charter Day\", in commemoration of the day President Manuel L. Quezon signed and approved into effect Commonwealth Act No. 326, creating the City of Bacolod: Provided, That the inauguration of the City of Bacolod shall be commemorated every 19th of October: Provided, further, That the highlights of the Masskara Festival shall be held every 4th Sunday of October."}},{"id":"PH-H9591-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Republic Act No. 7724, entitled: \"An Act Declaring October Nineteen Of Every Year A Special Nonworking Public Holiday In The City Of Bacolod To Be Known As ‘Bacolod City Charter Day’,\" and any law, presidential decree or issuance, executive order, letter of instruction, administrative order, rule or regulation contrary to or inconsistent with the provisions of this Act are hereby repealed, modified or amended accordingly."}},{"id":"PH-H9591-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"- This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9592"] = {"id":"PH-H9592","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11147_2018.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Increasing the Bed Capacity of the Narra Municipal Hospital in the Municipality of Narra, Province of Palawan From Ten (10) to One Hundred (100) Bed Capacity, and Naming It as the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital and Appropriaing Funds Therefor.","orig":"An Act Increasing the Bed Capacity of the Narra Municipal Hospital in the Municipality of Narra, Province of Palawan From Ten (10) to One Hundred (100) Bed Capacity, and Naming It as the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital and Appropriaing Funds Therefor."},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11147","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11147_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9592-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The authorized bed capacity of the Narra Municipal Hospital in the Municipality of Narra, Province of Palawan is hereby increased from ten (10) to one hundred (100) bed capacity and shall be now known as the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital."}},{"id":"PH-H9592-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The existing service facilities and professional health care services of the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital are hereby upgraded to conform with and be commensurate to the increase in bed capacity as provided in Section 1 hereof."}},{"id":"PH-H9592-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and properties, including buildings, sites, and improvements thereof, obligations, funds and appropriations of the Narra Municipal Hospital are hereby transferred to the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital."}},{"id":"PH-H9592-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Provincial Government of Palawan shall provide for the necessary funds to support the increase in bed capacity of the Governor Alfredo Mendoza Abueg, Sr. Memorial Hospital and the corresponding upgrading of its facilities and services. The Secretary of Health shall include in the Department's program the subsidy support for the capital outlay requirements of the said hospital."}},{"id":"PH-H9592-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Republic Act No. 6917, establishing a ten (10)-bed capacity Narra Municipal Hospital, is hereby repealed. All other laws, decrees, orders, issuances, rules and regulations, or parts thereof which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H9592-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9593"] = {"id":"PH-H9593","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11148_2018.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Scaling Up the National and Local Health and Nutrition Programs Through a Strengthened Integrated Strategy for Maternal, Neonatal, Child Health and Nutrition in the First One Thousand (1,000) Days of Life, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Scaling Up the National and Local Health and Nutrition Programs Through a Strengthened Integrated Strategy for Maternal, Neonatal, Child Health and Nutrition in the First One Thousand (1,000) Days of Life, Appropriating Funds Therefor and for Other Purposes"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 11148","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-29","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11148_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9593-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title. — This Act shall be known as \"Kalusugan at Nutrisyon ng Mag-Nanay Act\"."}},{"id":"PH-H9593-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy. - The right to health is a fundamental principle guaranteed by the State. Section 15, Article II of the 1987 Constitution emphasizes that \"The State shall protect and promote the right to health of the people and instill health consciousness among them\". Moreover, pursuant to various international human rights instruments and agreements that the State adheres to, the State guarantees the right to adequate food, care and nutrition to pregnant and lactating mothers, including adolescent girls, women of reproductive age, and especially children from zero (0) to two (2) years old.\nFurthermore, the State commits to the Philippine Development Plan and the national plans on nutrition to contribute to the improvement of the quality of human resource in the country, and the reduction of maternal and child mortality and stunting.\nThe State declares its determination to eliminate hunger and reduce all forms of malnutrition. The State further maintains that ensuring healthy lives, promoting well-being, ending hunger and food insecurity, and achieving good nutrition for all at all ages are essential to the attainment of sustainable development.\nAs such, the State prioritizes nutrition for adolescent females, pregnant and lactating women, infants and young children, to be implemented in an integrated manner by all branches of government, using a whole-of-government approach in collaboration with civil society organizations and the private sector.\nTowards this end, the State scales up nutrition intervention programs in the first one thousand (1,000) days of a child's life, and allocates resources in a sustainable manner to improve the nutritional status and to address the malnutrition of infants and young children from zero (0) to two (2) years old, adolescent females, pregnant and lactating women, as well as to ensure growth and development of infants and young children."}},{"id":"PH-H9593-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Objectives. - This Act specifically aims to:\n(a) Provide comprehensive, sustainable, multisectoral strategies and approaches to address health and nutrition problems of newborns, infants and young children, pregnant and lactating women and adolescent females, as well as multi-factorial issues that negatively affect the development of newborns, infants and young children, integrating the short, medium and long-term plans of the government to end hunger, improve health and nutrition, and reduce malnutrition;\n(b) Provide a policy environment conducive to nutrition improvement;\n(c) Provide evidence-based nutrition interventions and actions which integrate responsive caregiving and early stimulation in a safe and protective environment over the first one thousand (1,000) days as recommended by the United Nations Children's Fund (UNICEF) and the World Health Organization (WHO), as well as nutrition-specific and nutrition-sensitive mechanisms, strategies, programs and approaches in implementing programs and projects to improve nutritional status, and to eradicate malnutrition and hunger;\n(d) Strengthen and define the roles of the Department of Health (DOH), the National Nutrition Council (NNC), and other government agencies tasked to implement nutrition programs in the first one thousand (1,000) days;\n(e) Institutionalize and scale up nutrition in the first one thousand (1,000) days in the national plan on nutrition, the early childhood care and development intervention packages developed by the NNC, the Philippine Development Plan, the National Plan of Action for Children, the regional development plans, and local government units' (LGUS) investment plans for health and nutrition;\n(f) Ensure the meaningful, active and sustained participation, partnership and cooperation of NNC-member agencies, other National Government Agencies (NGAs), LGUs, civil society organizations ( CSOs), and the private sector, in an integrated and holistic manner, for the promotion of the health and nutritional well-being of the population, prioritizing interventions in areas with high incidence and magnitude of poverty, Geographically Isolated and Disadvantaged Areas (GIDA), and in hazard and conflict zones;\n(g) Strengthen enforcement of Executive Order No. 51, otherwise known as the \"National Code of Marketing of Breastmilk Substitutes, Breastmilk Supplements and Other Related Products\" or the \"Milk Code\", and Republic Act No. 10028, otherwise known as the \"Expanded Breastfeeding Promotion Act of 2009\", to protect, promote, and support optimal infant and young child feeding and maternity protection, and in consultation with the stakeholders in the public and private sectors, consider the new recommendations from the World Health Assembly (WHA) Resolution 69.9 to end the inappropriate promotion of food for infants and young children;\n(h) Strengthen the implementation of other nutrition related laws, programs, policies and guidelines including multisectoral integration, gender equality and promotion of the United Nations Convention on the Rights of the Child (UNCRC); and\n(i) Strengthen the family community support systems with the active engagement of parents and caregivers, with support from LGUs, the NGAs, CSOs, and other stakeholders."}},{"id":"PH-H9593-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"S caling Up Health and Nutrition for the First One Thousand (1,000) Days of Life. - The DOH, the NNC, the Department of Agriculture (DA), in coordination with other NGAs, the LGUs, the CSOs, and other stakeholders, shall develop a comprehensive and sustainable strategy for the first one thousand (1,000) days of life to address the health, nutrition, and developmental problems affecting infants, young children, adolescent females, and pregnant and lactating women. It shall operationalize the latest national plan on nutrition, integrating the short, medium and long-term plans of the government in response to the global call to eradicate hunger, improve nutrition, and prevent and manage malnutrition, as one (1) of the seventeen (17) Sustainable Development Goals (SDGs)."}},{"id":"PH-H9593-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Coverage. - This Act covers those who are nutritionally-at-risk, especially pregnant and lactating women, particularly teenage mothers, women of reproductive age, adolescent girls, and all Filipino children who are newly born up to age twenty-four (24) months.\nPriority shall be given to those who reside in disaster-prone areas and GIDA, such as areas that are isolated due to distance, inaccessibility to transportation, and weather conditions, unserved and underserved communities and other areas identified to have high incidences of poverty, those persons belonging to the vulnerable sector, communities in or recovering from situation of crisis or armed conflict and recognized as such by a government body.\nThe NNC shall prioritize LGUs, which meet any of the following criteria:\n(a) With the highest prevalence of undernutrition and nutrient-deficiency among pregnant and lactating women and children aged zero (0) to two (2) years;\n(b) Availability of facilities or capability to implement the program; and\n(c) Prioritizes such program in their locality and willingness to provide counterpart resources for its implementation."}},{"id":"PH-H9593-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Definition of Terms. - For purposes of this Act, the following terms are defined as follows:\n(a) Breastmilk Substitut e refers to any type of milk, in either liquid or powdered form, including soy milk and follow-up formula, that are specifically marketed for feeding infants and young children up to the age of three (3) years;\n(b) Chronic Energy Deficien cy (CED), or acute undernutrition, refers to a condition where there is negative energy balance due to inadequate food and nutrient intake, problems in absorption, relatively rare or excessive nutrient loss mostly due to infections and malignancies;\n(c) Civil Society Organizations (CSOs) refer to non-State actors whose aims are neither to generate profits nor to seek governing power, such as nongovernment organizations (NGOs), professional associations, foundations, independent research institutes, community-based organizations (CBOs), faith-based organizations, people's organizations, social movements, networks, coalitions, and labor unions, which are organized based on ethical, cultural, scientific, religious or philanthropic considerations;\n(d) Early S timulation refers to the process where infants and young children receive external stimuli to interact with others and their environment. It provides different opportunities for the child to explore, develop skills and abilities in a natural way and understand what is happening around them. Examples of early stimulation are language, motor and sensory stimulation with the aim of optimizing their cognitive, physical, emotional and social abilities, to avoid undesired states in development;\n(e) First one thousand (1,000) days of life refers to the period of a child's life, spanning the nine (9) months in the womb starting from conception to the first twenty-four (24) months of life, which is considered to be the critical window of opportunity to promote health and development and prevent malnutrition and its life-long consequences;\n(f) Geographically Isolated and Disadvantaged Are as (GIDA) refer to areas that are isolated due to distance or geographical isolation, weather conditions and lack of modes of transportation. This also refers to unserved and underserved communities and other areas identified to have access or service delivery problems, high incidence of poverty, presence of vulnerable sector, communities in or recovering from situation of crisis or armed conflict, and those recognized as such by a government body;\n(g) Low birth weight refers to weight at birth of an infant, whether born full term or preterm, of less than 2,500 grams or 5.5 pounds, or 5 pounds and 8 ounces;\n(h) Malnutrition refers to deficiencies, excesses or imbalances in a person's intake of protein, energy (carbohydrates and fats) and/or nutrients covering both undernutrition which includes suboptimal breastfeeding, stunting, wasting or thinness, underweight and micronutrient deficiencies or insufficiencies, as well as overnutrition, which includes overweight and obesity;\n(i) M oderate Ac ute Malnutrition (MAM) refers to low weight-for-length/height, defined as between two (2) and three (3) Standard Deviations (SD) below the median (<-2 up to -3 SD) of the WHO growth standards or a Mid-Upper Arm Circumference (MUAC) measurement of less than one hundred twenty-five millimeters (<125mm) and greater than or equal to one hundred fifteen millimeters (>115mm);\n(j) Nutrition-sensitive interventions and programs refer to interventions or programs that address the underlying determinants of maternal, fetal, infant and child nutrition and development, such as those pertaining to food security, social protection, adequate caregiving resources at the maternal, household and community levels; and access to health services and a safe and hygienic environment, and incorporate specific nutrition goals and actions. Nutrition-sensitive programs can serve as delivery platforms for nutrition-specific interventions, potentially increasing their scale, coverage, and effectiveness;\n(k) Nutrition-specific interventions and programs refer to interventions or programs that address the immediate determinants of maternal, fetal, infant and child nutrition and development, adequate food and nutrient intake, feeding, caregiving and parenting practices, and low burden of infectious diseases;\n(l) Nutritionally-at-risk pregnant women refers to pregnant women, including teenage mothers, with a low pre-pregnancy body mass index (BMI) or those who do not gain sufficient weight during pregnancy, with any of the following predisposing factors: narrowly-spaced pregnancies and births, situated in families with low income, with large number of dependents where food purchase is an economic problem, has previously given birth to a preterm or low birth weight infant, or other unfavorable prognostic factors, such as obesity or anemia, with diseases which influence nutritional status such as diabetes, tuberculosis, drug addiction, alcoholism and mental disorder;\n(m) Overweight and obesit y refer to the abnormal or excessive fat accumulation that may impair health. It is measured by BMI, a simple index of weight-for-height, which is commonly used to classify overweight and obesity among adults. BMI is calculated by dividing a person's weight in kilograms by the square of his/her height in meters (kg/m2). According to the WHO, adults with a BMI greater than or equal to twenty-five (25) are overweight and a BMI greater than or equal to thirty (30) is obese. For children, it is defined as the percentage of children aged zero (0) to fifty-nine (59) months whose weight for length/height is above two (2) SD (overweight) or above three (3) SD ( obese) from the median of the WHO Child Growth Standards;\n(n) Responsive caregiving refers to the method where the caregiver pays prompt and close attention with affection to what the child is signaling and then provides a response that is appropriate to the child's immediate behavior, needs and developmental state;\n(o) S evere A cute Malnutrition ( SAM) refers to very low weight for length/height, defined as less than three (3) SD below the median (<-3SD) of the WHO Growth Standards, characterized by visible severe wasting, or by the presence of bipedal pitting edema, or a MUAC measurement of less than one hundred fifteen millimeters (<115mm); and\n(p) Stunting refers to chronic undernutrition during the most critical periods of growth and development in early life. It is defined as the percentage of children aged zero (0) to fifty-nine (59) months whose height for age is below minus two (2) SD (moderate stunting) and minus three (3) SD (severe stunting) from the median of the WHO Child Growth Standards."}},{"id":"PH-H9593-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Program Implementation. - The DOH, in coordination with the NNC, the DA, the LGUs and other NGAs concerned, shall be responsible for the implementation of this Act. It shall be implemented at the barangay level through the rural health units and/or barangay health centers, in coordination with the Sangguniang Barangay. The Barangay Nutrition Scholars (BNS) and the Barangay Health Workers (BHWs) shall be mobilized and provided with resources and benefits to carry out their tasks.\nThe LGUs are encouraged to integrate maternal, neonatal, child health and nutrition programs in the local nutrition action plans and investment plans for health.\nThe NNC and other concerned NGAs shall provide appropriate technical assistance to respective LGU counterparts in the development, formulation, and implementation of this Act."}},{"id":"PH-H9593-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Program Components. - The program shall include health and nutrition services and interventions provided at the different life stages. The LGUs, NGAs, concerned CSOs, and other stakeholders shall work together to ensure the delivery of these services and interventions.\n(a) Prenatal Period (First Two Hundred Seventy (270) Days). – Prenatal care services at the facility and community level shall include, but not be limited to, the following:\n(1) Pregnancy tracking and enrollment to antenatal care services (ANC);\n(2) Regular follow up to complete the recommended minimum number of quality ANC care visits with proper referral for high-risk pregnancies;\n(3) Provision of maternal immunizations including tetanus and diphtheria toxoid vaccine, and other vaccines as appropriate;\n(4) Empowering women on the preparation of birth and emergency plans, and appropriate plans for breastfeeding and rooming-in, including counselling;\n(5) Counselling on maternal nutrition, appropriate infant and young child feeding practices;\n(6) Early identification and management of nutritionally at-risk pregnant women and pregnant adolescent females and provision of ready-to-use supplementary food (RUSF) in addition to dietary supplementation; (7) Provision of micronutrient supplements such as iron, folic acid, calcium, iodine and other micronutrients deemed necessary;\n(8) Promotion of the consumption of iodized salt and foods fortified with micronutrients deemed necessary;\n(9) Assessment of risk for parasitism and provision of anti-helminthic medicines;\n(10) Provision of oral health services including oral health assessment;\n(11) Counselling on proper hand-washing, environmental sanitation, and personal hygiene;\n(12) Counselling on, and utilization of, responsible parenthood and family health services;\n(13) Counselling on nutrition, smoking cessation, and adoption of healthy lifestyle practices;\n(14) Philippine Health Insurance Corporation (PhilHealth) enrollment and linkages to facility and community-based health and nutrition workers and volunteers;\n(15) Social welfare support to improve access to health and nutrition services, such as, but not limited to, dietary supplementation, healthy food products and commodities for nutritionally-at-risk pregnant women belonging to poorest of the poor families, including those with disabilities;\n(16) Maternity protection during pregnancy;\n(17) Counselling and support to parents and caregivers on parent / caregiver-infant/child interaction for responsive care and early stimulation for early childhood development;\n(18) Provision of counselling and psychosocial support to parents and caregivers with priority to high-risk pregnant women and adolescent females belonging to poorest of the poor families; and\n(19) Others as may be determined based on international and national guidelines and evidence generated locally.\n(b) Wo men A bout to Give Birth and Immediate Postpartum Period. - Health and nutrition services at the facility and community level shall include, but not be limited to, the following:\n(1) Adherence to the couple's birth, breastfeeding, and rooming-in plans;\n(2) Provision of mother-friendly practices during labor and delivery in line with, and in compliance with, Mother and Baby-Friendly Health Facility Initiative (MBFHFI), Republic Act No. 10028, otherwise known as the \"Expanded Breastfeeding Promotion Act of 2009\", Executive Order No. 51 or the \"Milk Code\", and other related administrative issuances of the DOH on maternal and newborn care;\n(3) Monitoring of the progress of labor and the well-being of both the mother and the fetus, and provision of interventions to any health issue that may arise;\n(4) Identification of high-risk newborns that will be delivered; the premature, small for gestational age (SGA), and/or low birth weight infants; and the provision of preventive interventions to reduce complications of prematurity or low birth weight;\n(5) Coverage and utilization of PhilHealth benefit packages for maternal care;\n(6) Nutrition counselling and provision of nutritious food and meals at the facility, most especially for women who gave birth to babies who are preterm, SGA, or low birth weight, until discharged;\n(7) Provision of lactation management services to support breastfeeding initiation and exclusive breastfeeding for six (6) months, most especially for caesarean deliveries, and thereafter until discharged;\n(8) Counselling on proper hand-washing, environmental sanitation, and personal hygiene;\n(9) Counselling on, and utilization of, modern methods of family planning and access to reproductive health care services, as defined in Republic Act No. 10354, otherwise known as \"The Responsible Parenthood and Reproductive Health Act of 2012\";\n(10) Maintenance of non-separation of the mother and her newborn and rooming-in for early breastfeeding initiation;\n(11) Assurance of women and child-friendly spaces during calamities, disasters, or other emergencies;\n(12) Provision of support to fathers and caregivers to ensure their commitment to support the mother and the child on proper health and nutrition care and provide necessary counselling and positive parenting support interventions;\n(13) Counselling and support to parents and caregivers on parent / caregiver-infant / child interaction for responsive care and early stimulation for early childhood development; and\n(14) Others as may be determined based on international and national guidelines and evidence generated locally.\n(c) Postpartum and Lactating Women. - Health and nutrition services at the facility and community level shall include, but not be limited to, the following:\n(1) Follow-up visits to health facilities where they gave birth;\n(2) Home visits for women in difficult-to-reach communities especially if located in a GIDA;\n(3) Lactation support and counselling from birth up to two (2) years and beyond, including those women who will return to work and for women in the informal economies, and those with breastfeeding difficulties;\n(4) Nutrition assessment and counselling to meet the demands of lactation in health facilities and workplaces;\n(5) Identification and management of malnutrition of chronically energy deficient (CED) and nutritionally-at-risk postpartum and lactating women, including adolescent mothers, and provision of RUSF in addition to dietary supplementation, as appropriate;\n(6) Organization of community-based mother support groups and peer counsellors for breastfeeding in cooperation with other health and nutrition workers;\n(7) Lactation breaks for women in the workplaces including micro, small and medium enterprises;\n(8) Availability of lactation stations in the workplaces, both in government and in the private sector, informal economy workplaces, and in public places and public means of transportation as stipulated in Republic Act No. 10028, otherwise known as the \"Expanded Breastfeeding Promotion Act of 2009\" and its implementing rules and regulations;\n(9) Organization of breastfeeding support groups in workplaces, in cooperation with occupational health workers and human resource managers trained in lactation management for the workplace;\n(10) Provision of micronutrient supplements including iron, folic acid, Vitamin A and other micronutrients deemed necessary;\n(11) Promotion of the consumption of iodized salt and foods fortified with micronutrients deemed necessary;\n(12) Provision of oral health services;\n(13) Counselling on, and utilization of, modern methods of family planning, and access to reproductive health care services, as defined in Republic Act No. 10354, otherwise known as \"The Responsible Parenthood and Reproductive Health Act of 2012\";\n(14) Social welfare support to improve access to health and nutrition services, such as, but not limited to, dietary supplementation, healthy food products and commodities for CED and nutritionally-at-risk postpartum and/or lactating women belonging to poorest of the poor families;\n(15) Assurance of women-friendly and child-friendly spaces where mothers and their infants will be able to continue breastfeeding during calamities, disasters, or other emergencies;\n(16) Provision of support to fathers and caregivers to ensure their commitment to support the mother and the child on proper health and nutrition care and provide necessary counselling and positive parenting support intervention;\n(17) Counselling and support to parents and caregivers on parent/caregiver-infant/child interaction for responsive care, and early stimulation for early childhood development; and\n(18) Others as may be determined based on international and national guidelines and evidence generated locally.\n(d) Birth and Newborn Period (Twenty-eight (28) Days). - Health and nutrition services at the facility and community level shall include, but not be limited to, the following:\n(1) Provision of baby-friendly practices during delivery in line, and in compliance, with the MBFHFI and essential newborn care protocol of the DOH in all facilities providing birthing services;\n(2) Provision of early and continuous skin-to-skin contact to all full-term babies and continuous kangaroo mother care for small babies born preterm and low birth weight, in compliance with the newborn protocol of the DOH in all facilities providing birthing services;\n(3) Maintenance of non-separation of the mother and her newborn from birth for early breastfeeding initiation and exclusive breastfeeding;\n(4) Provision of routine newborn care services such as eye prophylaxis, Vitamin K supplementation, and immunizations;\n(5) Administration of newborn screening and newborn hearing screening;\n(6) Availment and utilization of appropriate PhilHealth benefit packages for the newborn including the preterm, low birth weight and small babies;\n(7) Provision of early referral to higher level facilities to manage illness and/or other complications;\n(8) Availability of human milk pasteurizer for strategic level two (2) and level three (3) facilities with neonatal intensive care units to ensure breastmilk supply for small babies born preterm and low birth weight within its facility, the service delivery network it serves, and for use of infants and young children during emergencies and disasters;\n(9) Assurance of a child-friendly space where exclusively breastfed infants will be able to continue breastfeeding during calamities, disasters or other emergencies;\n(10) Social welfare support to improve access to health and nutrition services for newborns belonging to poorest of the poor families;\n(11) Facilitate the prompt birth and death registration, including fetal deaths, including restoration and reconstruction of birth and death registration documents destroyed during disasters;\n(12) Counselling and support to parents and caregivers on parent/caregiver-infant / child interaction for responsive care and early stimulation for early childhood development;\n(13) Provision of support to parents and caregivers on early stimulation and responsive care for infants; and\n(14) Others as may be determined based on international and national guidelines and evidence generated locally.\n(e) First Si x (6) Months of Infanc y (One Hundred Eighty (180) Days). – Health (and nutrition services at the facility and community level shall include, but not be limited to, the following:\n(1) Provision of continuous support to mother and her infant for exclusive breastfeeding, including referral to trained health workers on lactation management and treatment of breast conditions;\n(2) Provision of appropriate and timely immunization services integrated with assessment of breastfeeding, early child development, growth monitoring and promotion, and Infant and Young Child Feeding (TYCF) counselling;\n(3) Growth and development monitoring and promotion of all infants less than six (6) months old especially those who had low birth weight, are stunted, or had acute malnutrition;\n(4) Counselling household members on hand-washing, environmental sanitation, and personal hygiene;\n(5) Provision of early referral to higher level health facilities to manage common childhood illnesses including acute malnutrition;\n(6) Identification and management of moderate or severe acute malnutrition among infants less than six (6) months old and provision of lactation management services and management of medical conditions contributing to malnutrition;\n(7) Counselling and support to parents and caregivers on parent/caregiver-infant/child interaction for responsive care and early stimulation for early childhood development;\n(8) Social welfare support to improve access to health and nutrition services for newborns belonging to poorest of the poor families;\n(9) Provision of support to fathers and caregivers to ensure their commitment to support the mother and the child on proper health and nutrition care and provide necessary counselling and positive parenting support interventions;\n(10) Assurance of women and child-friendly spaces during calamities, disasters, or other emergencies where health and nutrition services for women and children shall be provided; and\n(11) Others as may be determined based on international and national guidelines and evidence generated locally.\n(f) Infants S ix (6) Months up to Two (2) Years of A ge. - Health and nutrition services at the community level shall include, but not be limited to, the following:\n(1) Timely introduction of safe, appropriate, and nutrient-dense quality complementary food with continued and sustained breastfeeding for all infants from six (6) months up to two (2) years of age, with emphasis on the use of suitable, nutrient-rich, home-prepared, and locally available foods that are prepared and fed safely;\n(2) Provision of nutrition counselling on complementary food preparation and feeding to mothers and caregivers;\n(3) Dietary supplementation of age-appropriate and nutrient-dense quality complementary food;\n(4) Growth and development monitoring and promotion in health facilities and at home;\n(5) Provision of routine immunizations based on the latest DOH guidelines;\n(6) Provision of micronutrient supplements deemed necessary;\n(7) Management of common childhood illnesses based on WHO and DOH guidelines;\n(8) Management of moderate and severe acute malnutrition using national guidelines and proper referral to higher level health facilities as appropriate, for treatment and management, especially those with serious medical complications;\n(9) Provision of oral health services including application of fluoride varnish to prevent dental caries;\n(10) Provision of anti-helminthic tablets for children one (1) to two (2) years old as appropriate;\n(11) Availability of potable source of water, counselling of household members on hand-washing, environmental sanitation, and personal hygiene, and support for sanitation needs of households to reduce food, water, and vector-borne diseases;\n(12) Counselling and support to parents and caregivers on parent/caregiver-infant/child interaction for responsive care, and early stimulation for early childhood development, and referral for development delays and other disabilities for early prevention, treatment and rehabilitation;\n(13) Social welfare support to improve access to health and nutrition services such as, but not limited to, dietary supplementation, complementary food, other healthy food products and commodities, assessment and referral for development delays and other disabilities for early prevention, treatment and rehabilitation for infants six (6) months and above who belong to poorest of the poor families;\n(14) Support for home kitchen gardens wherever feasible;\n(15) Provision of locally available grown crops, vegetables and fruits in addition to other agricultural products to be used in complementary feeding and dietary supplementation;\n(16) Protection against child abuse, injuries and accidents including the provision of first aid, counselling and proper referrals; and\n(17) Others as may be determined based on international and national guidelines and evidence generated locally."}},{"id":"PH-H9593-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Health and Nutrition of Adolescent Females. - To address the cyclical nature of malnutrition among the population, delivery of health and nutrition services for adolescent females ten (10) to eighteen (18) years old at facility, school, and community levels shall include, but not be limited to, the following:\n(a) Assessment of health and nutrition status and identification of nutritionally-at-risk adolescent girls, as well as provision of ready to use supplementary food or ready to use therapeutic food for nutritionally-at-risk adolescent females, as appropriate;\n(b) Provision of age-appropriate immunizations based on the latest DOH guidelines;\n(c) Provision of oral health services including oral health assessment;\n(d) Provision of anti-helminthic drugs for deworming;\n(e) Counselling on proper hand-washing, environmental sanitation, and personal hygiene;\n(f) Provision of micronutrient supplements according to guidelines of the DOH, in partnership with the Department of Education (DepEd);\n(g) Promotion of the consumption of iodized salt and foods fortified with micronutrients that may be deemed necessary;\n(h) Referral to appropriate health facilities to manage menstruation irregularities or abnormalities that contribute to anemia and blood loss, and to manage complicated illnesses including moderate, severe acute malnutrition;\n(i) Counselling on proper nutrition, mental health, avoidance of risk-taking behaviors, smoking cessation, adoption of healthy lifestyle practices, and family health; and\n(j) Others as may be determined based on international guidelines and evidence generated locally."}},{"id":"PH-H9593-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Other Program Components. - The LGUs, NGAs, concerned CSOs, and other stakeholders shall likewise include the following cross-cutting components in the implementation of the program:\n(a) National and local health and nutrition investment planning and financing;\n(b) Policy, standards, and guideline development;\n(c) Health and nutrition promotion and education, social mobilization and community organization, including advocacy;\n(d) Service delivery;\n(e) Health and nutrition human resources capacity development;\n(f) Sectoral collaboration and partnerships;\n(g) Logistics and supply management;\n(h) Knowledge management and information; and\n(i) Monitoring and evaluation, and research and development."}},{"id":"PH-H9593-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Nutrition in the Aftermath of N atural Disasters and Calamities. – Areas that are affected by disasters and emergency situations, both natural and man-made must be prioritized in the delivery of health and nutrition services, and psychosocial services interventions. NGAs and LGUs are mandated to immediately provide emergency services, food supplies for proper nourishment of pregnant and lactating mothers, and children, specifically those from zero (0) to two (2) years old. Women, infant and child-friendly spaces shall be prepared and ready to accommodate women and their children, provide their daily necessities such as food, clothing, clean water, and shelter; readily available breastfeeding support and counselling for those with children up to two (2) years or beyond, as well as provision and guidance on the appropriate complementary food for children over six (6) months old.\nDonations of milk formula, breastmilk substitutes, and/or products covered by the Milk Code without the approval of the Inter-Agency Committee (IAC) created under Executive Order No. 51, Series of 1986, shall be prohibited in order to protect the health and nutrition of pregnant and lactating women, infants and young children before, during and after a disaster.\nIn emergency situations, donations or assistance from the private sector, with no conflicts of interest or those not involved with manufacture, marketing, and sales of products covered by the scope of the Milk Code, shall be allowed immediately in the aftermath of natural disasters and calamities. Strict compliance with the Milk Code and its revised implementing rules and regulations (IRR) shall be observed, and options for mothers with breastfeeding problems will be provided, such as, but not limited to, the mobilization of breastfeeding support groups or strategic establishment of local milk banks.\nThe DOH and other relevant departments, in coordination with the National Disaster Risk Reduction and Management Council (NDRRMC), shall formulate guidelines and mechanisms in pursuit of this section, taking into consideration humanitarian, inclusive, gender and culture-sensitive standards for the protection of children, pregnant and lactating mothers, in accordance with Republic Act No. 10821, otherwise known as the \"Children's Emergency Relief and Protection Act\", its implementing rules and regulations, and the Comprehensive Emergency Program for Children."}},{"id":"PH-H9593-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Capacity-Building of Barangay Health and Nutrition Volunteers. - The DOH and the NNC, in coordination with LGUs, shall provide practical and effective training courses to BNSs, BHWs, and other personnel concerned to upgrade their skills and competence in the implementation of the services and interventions for the health and nutrition of women and children."}},{"id":"PH-H9593-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The National Nutrition Council (NNC ) Governing Board. - The NNC Governing Board shall be composed of the following:\n(a) Secretary of the DOH as the ex officio Chairperson;\n(b) Secretary of the DA as the ex offici o Vice Chairperson;\n(c) Secretary of the Department of the Interior and Local Government (DILG) as the e x officio Vice Chairperson;\n(d) Secretary of the DepEd;\n(e) Secretary of the Department of Social Welfare and Development (DSWD);\n(f) Secretary of the Department of Trade and Industry (DTI);\n(g) Secretary of the Department of Labor and Employment (DOLE);\n(h) Secretary of the Department of Science and Technology (DOST);\n(i) Secretary of the Department of Budget and Management (DBM);\n(j) Secretary of the National Economic and Development Authority (NEDA); and\n(k) Three (3) representatives from the private sector to be appointed by the President who shall come from any of the following: (1) health and nutrition professional organizations; (2) women sector; (3) farmer and fisherfolk; (4) urban poor; (5) organization or association of community health workers or BNS; (6) CSOs; and (7) academe and research institutions. Said representatives shall serve for a term of two (2) years.\nThe heads of departments may be represented by their duly designated representatives who shall be of a rank not lower than an Assistant Secretary.\nPersons from the private sector with conflicts of interest, especially as described in Executive Order No. 51, Series of 1986, are prohibited from being members of the Council.\nThe composition of the NNC's Secretariat and Technical Committee as defined in Executive Order No. 234, series of 1987, \"Reorganizing the National Nutrition Council\" shall be maintained."}},{"id":"PH-H9593-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Functions, Roles, and Responsibilities of the NNC. – The NNC, the highest policy making and coordinating body on nutrition, shall have the following functions and powers:\n(a) Formulate national nutrition policies, plans, strategies and approaches for nutrition improvement, including strategies on women, infant and young child, and adolescent nutrition;\n(b) Oversee and serve as a focal point in the integration of nutrition policies and programs of all member agencies and instrumentalities charged with the implementation of existing laws, policies, rules and regulations concerning nutrition;\n(c) Coordinate, monitor and evaluate nutrition programs and projects of the public and private sectors and LGUs to ensure their integration with national policies;\n(d) Receive grants, donations and contributions, in any form, from foreign governments, private institutions and other funding entities for nutrition programs and projects: Provided, That no conditions shall be made contrary to the policies or provisions of this Act;\n(e) Coordinate the joint planning and budgeting of member agencies to ensure funds for relevant nutrition programs and projects; to secure the release of funds in accordance with the approved programs and projects; and to monitor implementation and track public expenditure on these programs; and\n(f) Call upon any government agency and instrumentality for such assistance as may be required to implement the provisions of this Act."}},{"id":"PH-H9593-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Role of NNC Member A genc i es, Other NG AS and LGUs. - Member agencies shall be responsible for ensuring the implementation of programs and projects, development of promotive, preventive and curative nutrition programs, and integration of health and nutrition concerns into their respective policies and plans. It shall provide additional resources in any form, including technical assistance, sourced from its budget in support of local nutrition programs."}},{"id":"PH-H9593-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Procurement of Goods and S ervices. - The provisions of Republic Act No. 9184, otherwise known as the \"Government Procurement Reform Act\", notwithstanding, the government agencies concerned are hereby mandated to establish a liberalized mode of procurement for this program, subject to the approval of the Government Procurement Policy Board.\nThe public procurement for this program shall prioritize the participation of local and community-based producers, suppliers and / or service contractors."}},{"id":"PH-H9593-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Monitoring, Review and Assessment of the Program. - The NGAs and LGUs concerned shall regularly monitor, review and assess the impact and the effectivity of the program in consultation with their stakeholders."}},{"id":"PH-H9593-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"A ppropriations. – The amount needed for the initial implementation of this Act shall be charged against the appropriations of the DOH, DA, NNC and other relevant agencies. Thereafter, such sums as may be necessary for the continued implementation of this Act shall be included in the annual General Appropriations Act (GAA).\nThe DBM, in coordination with the Department of Finance (DOF), DOH, DA, NNC and other relevant agencies shall consider the prevalence of malnutrition and child mortality in determining the annual appropriations for the implementation of this Act.\nPriority LGUs identified by the NNC shall be eligible to receive from concerned NGAs supplementary funds necessary for the implementation of this Act. Said subsidy shall be included in the GAA."}},{"id":"PH-H9593-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Implementing Rules and Regulations (IRR). - Within ninety (90) days from the effectivity of this Act, the DOH shall, in coordination with the NNC Governing Board, and in consultation with stakeholders in the public and private sectors, promulgate the IRR necessary for the effective implementation of this Act."}},{"id":"PH-H9593-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"S eparability Clause. - If any provision of this Act or the application of such provision to any instrumentalities or entities or circumstances is held invalid or unconstitutional for any reason or reasons, the remainder of this Act or the application of such other provisions shall not be affected thereby."}},{"id":"PH-H9593-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, administrative orders or parts thereof inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H9593-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"- Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9594"] = {"id":"PH-H9594","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11149_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Philippine Citizenship to Kwok Hing Carlos Yeung","orig":"An Act Granting Philippine Citizenship to Kwok Hing Carlos Yeung"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11149","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-11-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11149_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9594-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mr. Kwok Hing Carlos Yeung is hereby granted Philippine citizenship with all the rights, privileges and prerogatives, and is likewise vested with the duties and obligations appurtenant thereto."}},{"id":"PH-H9594-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Mr. Kwok Hing Carlos Yeung shall take the Oath of Allegiance to the Republic of the Phihppines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H9594-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Mr. Yeung who shall thereupon enter into the full enjoyment of Philippine citizenship."}},{"id":"PH-H9594-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9595"] = {"id":"PH-H9595","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11150_2018.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"设立Surallah市","en":"An Act Establishing the South Cotabato State College in the Municipality of Surallah, Province of South Cotabato, Integrating Therewith the Surallah National Agricultural School Located in the Municipality of Surallah, Province of South Cotabato, and Appropriating Funds Therefor","orig":"An Act Establishing the South Cotabato State College in the Municipality of Surallah, Province of South Cotabato, Integrating Therewith the Surallah National Agricultural School Located in the Municipality of Surallah, Province of South Cotabato, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 11150","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-13","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11150_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9595-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment. - There is hereby established a state college in the Municipality of Surallah, Province of South Cotabato, to be known as the South Cotabato State College, hereinafter referred to as the College, and integrating therewith the Surallah National Agricultural School (SUNAS) located in the Municipality of Surallah, Province of South Cotabato. Its main campus shall be located in the same municipality."}},{"id":"PH-H9595-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"General Mandate. - The College shall primarily provide both advance instruction and research in agriculture, allied technological sciences, education, and arts and related sciences. It shall also undertake extension and development programs, and provide the necessary instructional and research leadership in agricultural, environmental and technological development in the Province of South Cotabato and in Region XII."}},{"id":"PH-H9595-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Curricular Offerings. - The College shall offer undergraduate and graduate courses in the fields of agriculture, environmental management, engineering, education, arts and sciences, and other degree courses within its areas of specialization and according to its capabilities, as the Board of Trustees may deem necessary to carry out its objectives and in order to meet the needs of the Province of South Cotabato and in Region XII.\nThe existing and any other future technical-vocational courses or programs under the supervision of the Technical Education and Skills Development Authority (TESDA) shall remain and continue to be offered by the College."}},{"id":"PH-H9595-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Administration. - The College shall have the general powers of a corporation set forth in Batas Pambansa Blg. 68, as amended, otherwise known as \"The Corporation Code of the Philippines\". The administration of the College and the exercise of its corporate powers shall be vested exclusively on the Board of Trustees and the President of the College."}},{"id":"PH-H9595-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Governing Board. - The governing board of the College shall be the Board of Trustees, hereinafter referred to as the Board, which shall be chaired and co-chaired by the Chairperson of the Commission on Higher Education (CHED) and the President of the College, respectively, with the following as members:\n(a) Chairperson of the Committee on Education, Arts and Culture of the Senate;\n(b) Chairperson of the Committee on Higher and Technical Education of the House of Representatives;\n(c) Regional Director of the National Economic and Development Authority (NEDA);\n(d) Regional Director of the Department of Agriculture (DA);\n(e) Regional Director of the TESDA;\n(f) President of the federation of faculty associations of the College;\n(g) President of the federation of student councils of the College;\n(h) President of the federation of alumni associations of the College; and\n(i) Two (2) prominent citizens from the private sector who have distinguished themselves in their profession or fields of specialization of the College.\nThe Board shall appoint the two (2) prominent citizens from among a list of at least five (5) qualified persons in the Province of South Cotabato, as recommended by the search committee to be constituted by the College President, in consultation with the Chairperson of the CHED and other members of the Board, based on the normal standards and qualifications for the position.\nThe two (2) prominent citizens shall serve for a term of two (2) years from the date of appointment."}},{"id":"PH-H9595-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Promulgation and Implementation of Policies. – The Board shall promulgate and implement policies in accordance with the declared State policies on education and other pertinent provisions of the Constitution on education, agriculture, science and technology, as well as the policies, standards and thrusts of the CHED under Republic Act No. 7722, otherwise known as the \"Higher Education Act of 1994\"."}},{"id":"PH-H9595-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers and Duties of the Board of Trustees. - The Board shall have the following specific powers and duties, in addition to its general powers of administration and the exercise of all the powers granted to the board of directors of a corporation under existing laws:\n(a) Approve the curricula, instructional programs, and rules of discipline drawn by the Administrative and the Academic Councils herein provided;\n(b) Appoint, upon the recommendation of the President of the College, the vice presidents, deans, directors, heads of the campuses, faculty members, and other officials and employees of the College;\n(c) Fix and adjust the salaries of faculty members, administrative officials and employees, subject to the provisions of the Revised Compensation and Position Classification System and other pertinent budget and compensation laws governing hours of service and such other duties and conditions as it may deem proper; to grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provision of existing law to the contrary notwithstanding; and to remove them for cause in accordance with the requirements of due process of law;\n(d) Fix the tuition fees and other necessary school charges, such as matriculation fees, graduation fees, and laboratory fees, as the Board may deem proper to impose, after due consultation with the involved sectors. The fees and charges, including government subsidies and other income generated by the College, shall constitute special trust funds, and shall be deposited in any authorized government depository bank, and all interests that shall accrue therefrom shall form part of the same funds for the use of the College. Any provision of existing law, rules or regulations to the contrary notwithstanding, any income generated by the College from tuition fees and other charges, as well as from the operation of auxiliary services and land grants, shall be retained by the College, and may be disbursed by the Board for instruction, research, extension or other programs/projects of the College: Provided, That all fiduciary fees shall be disbursed for the specific purposes for which these are collected: Provided, however, That if, for reasons beyond its control, the College shall not be able to pursue any project for which the funds have been appropriated and allocated under its approved program of expenditures, the Board may authorize the use of said funds for any reasonable purpose which, in its discretion, may be necessary and urgent for the attainment of the objectives and goals of the College;\n(e) Adopt and implement a socialized scheme of tuition and other school fees for greater access of poor but deserving students in accordance with Republic Act No. 10931, or \"The Universal Access to Quality Tertiary Education Act\";\n(f) Establish professorial chairs in the College and to provide fellowships for qualified faculty members, and scholarships to deserving students;\n(g) Receive and appropriate all sums as may be provided for the support of the College in the manner it may determine, in its discretion, in order to carry out the purposes and functions of the College;\n(h) Set the policies on admission and graduation of students;\n(i) Award honorary degrees upon persons in recognition of their outstanding contribution in the fields of education, public service, arts, science and technology, agriculture or any field of specialization within the academic competence of the College, and to authorize the awarding of certificates of completion of nondegree and nontraditional courses;\n(j) Establish research and extension centers to promote the development of the College;\n(k) Develop academic arrangements for institution capability building with appropriate institutions and agencies, public and private and local and foreign, and to appoint experts / specialists as consultants; part-time, visiting or exchange professors; scholars, researchers, as the case may be;\n(l) Adopt modern and innovative modes of transmitting knowledge for the promotion of greater access to education such as the use of information technology, the dual training system, open distance learning, and community laboratory;\n(m) Collaborate with the governing boards of the state universities and colleges (SUCs) within the Province of South Cotabato, under the supervision of the CHED and in consultation with the Department of Budget and Management (DBM), in restructuring the College to make it more efficient, relevant, productive and competitive;\n(n) Absorb non-chartered tertiary institutions within the Province of South Cotabato as branches and centers, in coordination with the CHED, and in consultation with the DBM, and to offer therein programs or courses to promote and carry out equal access to educational opportunities, as mandated by the Constitution;\n(o) Authorize an external management audit of the College, to be financed by the CHED, subject to the rules and regulations of the Commission on Audit (COA); and to institute reforms, including academic and structural changes, on the basis of the audit results and recommendations;\n(p) Develop consortia and other economic forms of linkages with local government units (LGUs), institutions and agencies, both public and private and local and foreign, in the furtherance of the purpose and objectives of the College;\n(q) Import economic, technical and cultural books and publications;\n(r) Enter into joint ventures with business and industry for the profitable development and management of the economic assets of the College, the proceeds from which shall be used for the development and strengthening of the College;\n(s) Receive in trust legacies, gifts and donations of real and personal properties of all kinds and to administer and dispose of the same, when necessary, for the benefit of the College, and subject to the limitations, directions and instructions of the donor, if any;\n(t) Authorize the construction or repair of its buildings, machinery, equipment and other facilities, and the purchase and acquisition of real property, including necessary supplies, materials and equipment;\n(u) Extend the term of the President of the College beyond the age of retirement, but not beyond the age of seventy (70) based on the guidelines, qualifications and standards set by the Board: Provided, That the President's performance has been rated by the Board as outstanding, and after unanimous recommendation by the search committee;\n(v) Delegate any of its powers and duties provided to the President and other officials of the College, as it may deem appropriate, so as to expedite the administration of the affairs of the College;\n(w) Establish policy guidelines and procedures for participative decision-making and transparency within the College;\n(x) Where most advantageous to the College, privatize the management of nonacademic services such as health, food, building or grounds or property maintenance, and such other similar activities; and\n(y) Promulgate rules and regulations as may be necessary to carry out the purposes and functions of the College."}},{"id":"PH-H9595-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Meetings of the Board. - The Board shall regularly convene at least once every quarter. However, the Chairperson of the Board may, upon three (3) days' prior written notice, call a maximum of two (2) special meetings whenever necessary.\nA quorum of the Board shall consist of a majority of all its members holding office at the time of the meeting: Provided, however, That either the Chairperson of the Board or the President of the College must be present in the meeting.\nIn the absence of the CHED Chairperson, a Commissioner of the CHED duly designated by the CHED Chairperson as representative in the meeting, shall have all the rights and responsibilities of a regular member: Provided, however, That during the meeting, the President of the College, as Vice Chairperson, shall be the Presiding Officer: Provided, further, That this provision notwithstanding, the Chairperson of the CHED is hereby authorized to designate a CHED Commissioner as the regular Chairperson of the Board, in which case said CHED Commissioner shall act as the Presiding Officer.\nIn case the Chairpersons of the House and Senate Committees on Education shall not be able to attend the Board meeting, they may designate their respective representatives to attend the said meeting, who shall have the same rights and responsibilities as a regular member of the Board.\nThe members of the Board shall not receive any salary, but shall be entitled to reimbursements for actual and necessary expenses incurred in attending the meetings of the Board or in connection with other official business authorized by resolution of the Board, subject to existing laws and regulations."}},{"id":"PH-H9595-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The College President. - The President shall serve for a term of four (4) years and shall be eligible for reappointment for another term : Provided, That in order to effect a smooth transition to a state college, the incumbent Vocational School Administrator of the Surallah National Agricultural School shall act as the Officer-in-Charge (OIC) pending the appointment of the first President of the College. Within six (6) months from the date of approval of this Act, the Board shall constitute the Search Committee for the Presidency.\nIn case of vacancy in the Office of the President by reason of death, compulsory retirement, resignation, removal for cause or incapacity of the President to perform the functions of the office, the Board shall have the authority to designate an OIC of the College pending the appointment of a new President.\nIn case of vacancy in the Office of the President as mentioned in the immediately preceding paragraph, the successor or the OIC shall serve only for the unexpired portion of the term.\nThe powers and duties of the President of the College, in addition to those specifically provided in this Act, shall be those usually pertaining to the Office of the President of similar colleges, and those delegated by the Board.\nThe salary of the President of the College shall be in accordance with the Revised Compensation and Position Classification System as modified by Joint Resolution No. 4 dated June 17, 2009 and other pertinent budget and compensation laws, and shall be comparable to that being received by the Presidents of similar educational institutions.\nThe President of the College shall be assisted by a Vice President for Academic Affairs and a Vice President for Administration, who shall be appointed by the Board upon recommendation of the President."}},{"id":"PH-H9595-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The Administrative Council. - There shall be an Administrative Council consisting of the President of the College, as Chairperson, and the vice presidents, deans, directors and other officials of equal rank, as members, whose duty is to review and recommend to the Board the policies governing the administration, management and development plan of the College."}},{"id":"PH-H9595-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Ac ademic Council. - There shall be an Academic Council to be composed of the President of the College, who shall act as Chairperson, and all the academic staff with the rank of at least an assistant professor, as members.\nThe Academic Council shall have the power to review and recommend the curricular offerings and rules of discipline of the College, subject to the approval of the Board. It shall fix the requirements for the admission of students, as well as for their graduation and the conferment of degrees, subject to review and approval by the Board through the President of the College. It shall have the disciplinary power over students of the College and shall formulate academic policies and rules and regulations on discipline, subject to the approval of the Board."}},{"id":"PH-H9595-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The Se cretary of the College. - The Board shall appoint a Secretary, who shall serve as such for both the Board and the College, and who shall keep all records and proceedings of the Board in addition to other duties and responsibilities. The Secretary shall serve upon each member of the Board the appropriate notice of the Board meetings."}},{"id":"PH-H9595-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Treasurer of the College. - The Treasurer of the Philippines shall be the e x officio treasurer of the College."}},{"id":"PH-H9595-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Facult y. – No political belief, gender preference, cultural or community affiliation or ethnic origin, and religious opinion or affiliation shall be a matter of inquiry in the appointment of faculty members of the College: Provided, however, That said appointment shall be subject to the guidelines, qualifications and standards set by the Board: Provided, further, That no member of the faculty shall teach for or against any particular church or religious sect."}},{"id":"PH-H9595-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Scholarship Program/Admission. - The College shall provide a scholarship program and other affirmative action programs to assist poor but deserving students who qualify for admission to the College. No student shall be denied admission to the College by reason of sex, religion, cultural or community affiliation or ethnic origin."}},{"id":"PH-H9595-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Academic Freedom and Institutional Autonomy. – The College shall enjoy academic freedom and institutional autonomy, pursuant to paragraph 2, Section 5 of Article XIV of the Constitution."}},{"id":"PH-H9595-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Authority to Loan or Transfer Apparatus/ Equipment/Supplies and Detail of Personnel. – The heads of the bureaus and offices of the national government are hereby authorized to loan or transfer, upon the request of the President of the College, such apparatus, equipment or supplies as may be needed by the College, and to detail employees for duty therein when, in the judgment of the head of bureau or office, such apparatus, equipment, supplies or services of such employees can be spared without serious detriment to the public service. The employees so detailed shall perform such duties as required of them by the President of the College, and the time so employed shall be counted as part of their regular service."}},{"id":"PH-H9595-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Assets, Liabilities and Personnel. - All assets, real and personal, personnel and records of the SUNAS, as well as liabilities or obligations, are hereby transferred to the College. The positions, rights, and security of tenure of faculty members and personnel employed therein under existing laws prior to the integration into the College shall be respected.\nAll parcels of land belonging to the government occupied by the SUNAS are hereby declared to be the property of the College and shall be titled under its name: Provided, That should the College cease to exist or be abolished or should such parcels of land aforementioned be no longer needed by the College, the same shall revert to the LGUs concerned."}},{"id":"PH-H9595-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Development Plan, Management Audit / Organizational/ A dministrative Ac ademic Structure. - Within the period of one hundred twenty (120) days after the approval of this Act, the College shall accomplish the following:\n(a) Submit a five (5)-year development plan, including its corresponding program budget to the CHED, for corresponding recommendation to the DBM;\n(b) Undergo a management audit in cooperation with the CHED; and\n(c) Accordingly set up its organizational, administrative, as well as academic structure, including the appointment of the College key officials."}},{"id":"PH-H9595-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Compliance with CHED Requirements. – The provisions of this Act notwithstanding, the establishment of the institution into a state college shall become effective only upon the determination and declaration by the CHED, based on the recommendation of a panel of experts it shall constitute for the purpose, that the institution has complied with the requirements for a college status based on CHED Memorandum Order No. 46, Series of 2012 (Policy-Standard to Enhance Quality Assurance (QA) in Philippine Higher Education Through an Outcomes-Based and Typology-Based QA) : Provided, That the panel may issue such a recommendation when the institution has substantially complied with the requirements for the grant of status as a state college.\nThe following operational requirements for a state college, as established by the CHED, shall be complied with:\n(a) Full-time permanent faculty members who have the relevant degrees as required by the CHED and experience in the subject areas they handle;\n(b) Degree programs characterized by a core curriculum that holistically develops thinking, problem solving, decision-making, communication, technical, and social skills in line with the mission of the College;\n(c) Learning resources and support structures that are appropriate for developing knowledge and skills in the specific natural science, social science, humanities, and professional disciplines offered by the College, including laboratories, books and journals, etc.;\n(d) Links with the community that would ensure the development of relevant academic and extension programs as well as the application of their learning outcomes; and\n(e) Outreach programs involving students in social-development oriented experiences that allow them to contextualize their knowledge within actual social and human experiences.\nAfter five (5) years of operation, it shall be evaluated by the CHED to determine its compliance with the requirements for a College classification according to the horizontal typology of higher education institutions (HEIS).\nMoreover, the College shall undergo the institutional sustainability assessment (ISA) process to ensure that an internal quality assurance (IQA) system has been established leading to sustainable offering of quality programs and services."}},{"id":"PH-H9595-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"A nnual Report. - On or before the fifteenth (15th) day of the second month after the opening of the regular classes each year, the Board shall file with the Office of the President of the Philippines, through the Chairperson of the CHED, and with both Houses of Congress, a detailed report on the progress, condition and needs of the College."}},{"id":"PH-H9595-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Tax Exemption. – The importation of economic, technical and cultural books or publications, which are for economic, technical, vocational, scientific, philosophical, historical or cultural purposes made by the College, upon certification by the CHED, shall be exempt from customs duties in accordance with the provisions of Republic Act No. 10863, otherwise known as the \"Customs Modernization and Tariff Act (CMTA)\".\nAll grants, bequests, endowments, donations and contributions made to the College to be used actually, directly and exclusively by the College shall be exempt from donor's tax and the same shall be allowed as allowable deductions from the gross income of the donor for purposes of computing the taxable income of the donor in accordance with the provisions of the National Internal Revenue Code of 1997, as amended."}},{"id":"PH-H9595-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"A ppropriations. - The amount necessary to carry out the provisions of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H9595-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Suppletory Application. - The provisions of Republic Act No. 8292, otherwise known as the \"Higher Education Modernization Act of 1997\", shall be an integral part of this Act and shall serve as part of the Governing Charter of the College."}},{"id":"PH-H9595-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Parity Clause. - All other powers, functions and privileges, responsibilities and limitations to state colleges and their officials under existing laws shall be deemed granted to or imposed upon the College and officials, whenever appropriate."}},{"id":"PH-H9595-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Implementing Rules and Regulations. - The Board, in consultation with the CHED, shall formulate the guidelines to fully implement the provisions of this Act within sixty (60) days from its effectivity."}},{"id":"PH-H9595-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Separability Clause. - If, for any reason, any part or provision of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H9595-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Repealing Clause. - All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H9595-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9596"] = {"id":"PH-H9596","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11151_2018.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Isla Communications Company, Inc., Presently Known as Innove Communications, Inc., Amending for the Purpose Republic Act No. 7372, Entitled \"An Act Granting the Isla Communications Co. a Franchise to Install, Operate and Maintain Telecommunications Services Within the Territory of the Republic of the Philippines and International Points and for Other Purposes\"","orig":"An Act Renewing for Another Twenty-Five (25) Years the Franchise Granted to Isla Communications Company, Inc., Presently Known as Innove Communications, Inc., Amending for the Purpose Republic Act No. 7372, Entitled \"An Act Granting the Isla Communications Co. a Franchise to Install, Operate and Maintain Telecommunications Services Within the Territory of the Republic of the Philippines and International Points and for Other Purposes\""},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 11151","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11151_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9596-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and S cope of Franchise. - Subject to the conditions established in this Act and the provisions of the Constitution and the provisions of laws, orders or issuances not inconsistent herewith, there is hereby granted to the Isla Communications Company, Inc., (ISLACOM), presently known as Innove Communications, Inc., its successors or assignees, the right, privilege and authority to construct, establish, install, lease, co-use, purchase, operate and maintain all types of mobile and fixed wireless telecommunications, including cellular, telephone system, broadband and internet services (such as, but not limited to, the transmission and reception of voice, data transmission, message service/messaging, electronic mail, data facsimile, audio and video, and all other improvements and innovations and convergence of services pertaining to or as may be applicable to mobile telecommunications technology) and use all the apparatus, conduits, appliances, receivers, transmitters, antennas, satellites and equipment necessary for the transmission / reception of data, messages, videos and signals, with the corresponding technological auxiliaries, facilities, distribution or relay stations, throughout the Philippines, as well as multi-channel microwave, fiber optic and satellite distribution systems that may be required for the purpose of linking together said mobile, fixed or convergent telecommunications network internally and externally to other mobile telecommunications network and traditional wireline telephone systems, whether domestic or international, whether directly or indirectly, through networks and, generally, to provide by means of this telecommunications system a telephone service and such other telecommunications services such as there may be demand for in the Philippines.\n\"There is hereby granted to the grantee, its successors or assignees, a franchise to engage in telecommunications services by installing, maintaining and operating telecommunications plants, exchanges, nationwide and/or regional transmission (backbone) network; terrestrial and microwave systems, lines, instruments, landlines; international and domestic undersea cables, stations, apparatus, telephone services; long distance toll services; international gateway facilities/services; traditional wireline telephone systems, whether domestic or international, whether directly or indirectly through, networks; public calling offices (payphones); station or stations and associated equipment and facilities for international satellite communications, such ground facilities as needed to deliver telecommunications services from the communications satellite system and ground terminal or terminals and such ground facilities shall not duplicate existing facilities of domestic common carriers and grantee shall operate as a carrier's carrier; any and all types of telecommunications services available through the use of space relay and repeater stations for domestic public communications with authority to receive and transmit messages, impressions, pictures, music, entertainment, advertising and signal throughout the Philippines and between the Philippines and ships at sea, airplanes and other conveyances; any and all kinds of equipment or maintenance for communications and the transmission of messages, data, video, pictures, impressions and signals; or any other means which may hereafter be used for communications in their stead; and to install, maintain, operate or lease, in whole or in part, telephone lines and systems and all other systems and lines of communications, within the territory of the Philippines and with other countries and territories.\n\"The grantee is authorized to carry on the business of providing to the public telecommunications services within the territory of the Republic of the Philippines and other countries and territories and, for the purpose of providing said telecommunications services, to construct, own and operate telecommunications system in and between provinces, cities and municipalities of the Republic of the Philippines and to lay, place and operate and maintain telecommunications lines in and between the territory of the Republic of the Philippines and other countries, including the construction, operation and maintenance of an international digital gateway facility, and to construct, maintain and operate and use all telecommunications apparatus necessary for the provision of telecommunications services and to install, construct and maintain telecommunications apparatus in, on, over or under the public roads, government rights-of-way, lands, bridges, rivers, waters, streets, lanes and sidewalks of said provinces, cities and municipalities, and to lay submarine telecommunications cables in the surrounding waters of the Philippines and for the purpose of connecting its telecommunications systems with other telecommunications systems operated by others within the Philippines and with the telecommunications systems of other countries, as may be necessary and best adapted to said provision of telecommunications services, and to connect and keep connected its telecommunications system to other telecommunications systems for the interconnection of telecommunications services within the territory of the Republic of the Philippines and between the Republic of the Philippines and other countries and territories.\"\n\"Section 2. M anner of Operation of Stations or Facilities. – The stations pr facilities of the grantee shall be constructed and operated in a manner as will, at most, result only in the minimum interference on the wavelengths or frequencies of existing stations or other stations which may be established by law, without in any way diminishing its own privilege to use its assigned wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof.\"\n\"Section 3. Right of the Government. - The radio spectrum is a finite resource that is part of the national patrimony and the use thereof is a privilege conferred upon the grantee by the State and may be withdrawn any time after due process.\n\"The President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations, transmitter systems, facilities and equipment of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations, transmitter systems, facilities and equipment during the period when these shall be so operated.\"\n\"Section 4. Powers of the National Telecommunications Commission. - The grantee shall not exercise any right or privilege under this franchise without first having obtained such Certificate of Public Convenience and Necessity and such other permits or licenses from the National Telecommunications Commission (NTC). This franchise shall not take effect nor shall any power be exercised by the grantee until the NTC shall have allotted to the grantee the frequencies and wavelengths to be used, determined the stations to and from which each frequency and wavelength may be used, and issued to the grantee a license for such use. The NTC, however, shall not unreasonably withhold or delay the grant of any such authority, permits or licenses.\n\"The stations of the grantee shall be so constructed and operated and the wavelengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services.\n\"The grantee may install, operate and maintain radio telecommunications system to provide a telephone service and other telecommunications services including mobile services within the territory of the Republic of the Philippines and between the Republic of the Philippines and ships at sea, aircraft in the air, and the telecommunications systems of other countries : Provided, That the location, installation or operation of any such radio telecommunications system must be previously approved by the NTC: Provided, further, That the NTC shall have the authority to supervise and regulate the installation or operation of such radio telecommunications system.\"\n\"Section 5. Excavation and Restoration Works. - For the purpose of erecting and maintaining poles or other supports for wires or other conductors for laying and maintaining underground wires, cables or other conductors, the grantee, its successors or assignees, shall be authorized to make excavations or lay conduits in any of the public places, roads, highways, streets, lanes, alleys, avenues, sidewalks, bridges of the provinces, cities and / or municipalities, with the prior approval of the Department of Public Works and Highways (DPWH) and the local government unit (LGU) concerned, as may be appropriate: Provided, however, That any public place, highway, road, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of erection of poles or other supports or the underground laying of wires, other conductors or conduits, shall be repaired and replaced in a workmanlike manner by said grantee, its successors or assignees, in accordance with the standards set by the DPWH and the LGU concerned. Should the grantee, its successors or assignees, after the ten (10)-day notice from the said authority, fail, refuse or neglect to repair or replace any part of a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by said grantee, its successors or assignees, then the DPWH or the LGU concerned shall have the right to have the same repaired and placed in good order and condition and charge the grantee, its successors or assignees, at double the amount of the costs and expenses for such repair or replacement.\"\n\"Section 6 . Term. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In any event that the grantee fails to operate continuously for two (2) years, this franchise shall be deemed i pso facto revoked.\"\n\"Section 7 . Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and not use its stations / facilities for obscene or indecent transmission, or for dissemination of deliberately false information, or willful misrepresentation, or assist in subversive or treasonable acts.\n\"The grantee shall operate and maintain all its stations, lines, cables, systems, and equipment for the transmission and reception of messages, signals, and pulses in a satisfactory manner at all times, and as far as economical and practicable, modify, improve, or change such stations, lines, cables, systems, and equipment to keep abreast with the advances in science and technology.\n\"The grantee shall improve and extend its services in areas not yet served, and in hazard- and typhoon-prone areas that shall be determined by the National Disaster Risk Reduction and Management Council or its legal successor in coordination with the NTC.\n\"The grantee shall also improve and upgrade its equipment, facilities and services, in order to ensure effective compliance with the objectives of Republic Act No. 10639 or the Free Mobile Disaster Alerts Act'.\"\n\"Section 8. Gross Receipts. – The grantee, its successors or assignees, shall keep a separate account of the gross receipts of the telecommunications service business transacted by it and shall furnish the Commission on Audit (COA) and the National Treasurer a copy of such account not later than January 31 of each year for the preceding twelve (12) months.\"\n\"Section 9 . Tax Provisio ns. – The grantee, its successors or assignees, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or thereafter may be required by law to pay, except radio telecommunications and electronic communications equipment, machinery, and spare parts needed in connection with the business of the grantee which shall be exempt from customs duties, tariffs and other taxes, as well as those declared exempt in this section. In addition thereto, the grantee, its successors or assignees, shall pay a value-added tax on all gross receipts of the business transacted under this franchise by the grantee, its successors or assignees, in the Philippines in lieu of any and all taxes of any kind, nature, or description levied, established, or collected by an authority whatsoever including, but not limited to, city, municipal, provincial, or national, from which the grantee is hereby expressly exempted effective from the date of the effectivity of this Act: Provided, That the grantee, its successors or assignees, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case amendment or repeal shall be applicable thereto.\"\n\"Section 10. Commitment to Provide and Promote the Creation of Employment Opportunities. - The grantee shall create employment opportunities and shall allow on-the-job trainings in their franchise operation: Provided, That priority shall be accorded to the residents in areas where their principal office is located : Provided, further, That the grantee shall follow the applicable labor standards and allowance entitlement under existing labor laws, rules and regulations and similar issuances: Provided, finally, That the employment opportunities or jobs created shall be reflected in the General Information Sheet (GIS) to be submitted to the Securities and Exchange Commission annually.\"\n\"Section 11. M obile Number Portability. - The grantee shall provide mobile number portability (MNP). It shall set up a mechanism for the purpose of implementing MNP. It shall interconnect directly or indirectly with the infrastructure, facilities, systems, or equipment of other telecommunications franchise grantees. It shall not install network features, functions or capabilities that will impede the implementation of a nationwide MNP system. The NTC shall issue rules and regulations for this purpose, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees.\"\n\"Section 12. Eminent Domain. - Subject to the limitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as may be reasonably necessary to further the establishment and efficient maintenance and operation of its telecommunications systems.\n\"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation of any land except such as is required for the actual and necessary purposes for which this franchise is granted.\"\n\"Section 13 . Rates f or S ervices. - The charges and rates of telecommunications services of the grantee, except the rates and charges on those that may hereafter be declared or considered as nonregulated services, whether flat rates or measured rates or variation thereof, shall be subject to the approval of the NTC or its legal successor.\"\n\"Section 14. Right of Interconnection. - The grantee is hereby authorized to connect or demand connection of its telecommunications systems to any other telecommunications systems installed, operated and maintained by any other duly authorized person or entity in the Philippines for the purpose of providing extended and improved telecommunications services to the terms and conditions mutually agreed upon by the parties concerned, subject to the review and modification of the NTC.\"\n\"Section 15. Books and Accounts. - The books and accounts of the grantee, its successors or assignees, shall always be open to the inspection of the COA or its authorized representatives, and it shall be the duty of the grantee to submit to the COA quarterly reports in duplicate showing the gross receipts and the net receipts for the past quarter and the general condition of the business.\"\n\"Section 16. Nonexclusivity. - The rights herein granted shall not be exclusive, and the rights and power to grant to any corporation, association, or person other than the grantee a franchise for the provision of telephone service or the installation, operation and maintenance of a telecommunications system shall not be impaired or affected by the granting of this franchise: Provided, that the telecommunications lines installed by virtue of any franchise for the provision of a telecommunications service or the installation, operation and maintenance of a telecommunications systems grant subsequent to this franchise shall be so placed as not to impair the efficient and effective operation of the telecommunications system installed under this franchise and actually in existence at the time of the granting of said subsequent franchise: Provided, further, That the NTC after hearing both parties interested may compel the grantee of this franchise or its successors or assignees to remove, relocate or replace their telecommunications lines but in such case the reasonable cost of the removal, relocation or replacement shall be paid by the grantee of the subsequent franchise or his successors or assignees to the grantee of this franchise or its successors or assignees.\"\n\"Section 17. W arranty in Favor of the National and Local Governments. – The grantee shall hold the national, provincial, city, and municipal governments of the Philippines free from all claims, liabilities, demands, or actions arising out of accidents causing injury to persons or damage to properties, during the construction or operation of the stations of the grantee.\"\n\"Section 18. Sale, Lease, Transfer, Usufruct, or Assignment of Franchise. - The grantee shall not sell, lease, transfer, grant the usufruct of, nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether as a whole or in part, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when the transfer is done: (a) through a stock exchange transaction; (b) for purposes of qualifying persons for election to the board; (c) to a corporation that is controlled by the same stockholders as that of the grantee; (d) to person, firm, company, corporation or entity with a valid and existing legislative franchise for telecommunications; or (e) where the grantee is the surviving corporation: Provided, That the foregoing limitations shall not apply to: (1) any transfer or issuance of shares of stock in the implementation of the requirement for the dispersal of the grantee's ownership pursuant to Section 19 of this Act; (2) any transfer or sale of shares of stock to a foreign investor or investors; (3) any issuance of shares to a foreign or local investor pursuant to or in connection with any increase in the grantee's authorized capital stock which results in the dilution of the stockholdings of the grantee's then existing stockholders; or (4) any combination thereof where such transfer, sale or issuance is effected in order to enable the grantee to raise the necessary capital or financing for the provision of the services for which the grantee has been incorporated or organized: Provided, further, That any such transfer, sale or issuance is in accordance with any applicable constitutional provision. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act.\"\n\"Section 19. Dispersal of Ownership. - In accordance with the constitutional provision to encourage public participation in public utilities, the grantee shall offer to Filipino citizens at least thirty percent (30%) or a higher percentage that may hereafter be provided by law of its outstanding capital stock in any securities exchange in the Philippines within five (5) years from the commencement of its operations: Provided, That in cases where public offer of shares is not applicable, the grantee shall apply other methods of encouraging public participation by citizens and corporations operating public utilities as allowed by law. Noncompliance therewith shall render the franchise ipso facto revoked.\"\n\"Section 20. Contract with Private Entities. - The grantee is authorized to contract the installation and operation of the telecommunications system which is the subject of this grant with entities with expertise in the field of telecommunications under such terms and conditions as may be approved by the NTC.\"\n\"Section 21. Reportorial Requirements. – The grantee shall submit an annual report to the Congress of the Philippines, through the Committee on Legislative Franchises of the House of Representatives and the Committee on Public Services of the Senate, on its compliance with the terms and conditions of the franchise and on its operations on or before April 30 of every year during the term of its franchise. The reportorial compliance certificate issued by Congress shall be required before any application for permit or certificate is accepted by the NTC.\"\n\"Failure of the grantee to submit the requisite and separate annual report to Congress shall be penalized with a fine in the amount of One million pesos (P1,000,500.00) per working day of noncompliance, the effectivity of which shall commence upon applicability with other telecommunications franchise grantees: Provided, That in the interim, the grantee shall be liable to pay the fine of Five hundred pesos (P500.00) per working day of noncompliance. The fine shall be collected by the NTC from the delinquent franchise grantee separate from the reportorial penalties imposed by the NTC and the same shall be remitted to the National Treasury.\"\n\"Section 22. Equality Clause. – Any advantage, favor, privilege, exemption, or immunity which may hereafter be granted shall i pso facto become part of this franchise and shall be accorded immediately and unconditionally to the herein grantee : Provided, That the foregoing shall neither apply to nor affect the provisions of telecommunications franchises concerning territory covered by the franchise, the life span of the franchise, or the type of service authorized by the franchise.\""}},{"id":"PH-H9596-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Renewal of Franchise. - The term of the franchise granted under Republic Act No. 7372 is hereby renewed for another twenty-five (25) years from the date of its expiration. This franchise shall be deemed ipso facto revoked in the event the grantee falls to operate continuously for two (2) years."}},{"id":"PH-H9596-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"S eparability Claus e. - If any of the sections or provisions of this Act is held invalid, all other provisions not affected thereby shall remain valid."}},{"id":"PH-H9596-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealability and Exclusivity Clause. - This franchise is granted with the understanding and upon condition that it shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided."}},{"id":"PH-H9596-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Repealing Clause. – All laws, decrees, executive orders, rules and regulations or parts or provisions thereof which are not consistent with this Act are hereby repealed, amended, or modified accordingly."}},{"id":"PH-H9596-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9597"] = {"id":"PH-H9597","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11152_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Land Transportation Office - Medellin Extension Office Into a Regular District Office and Appropriating Funds Therefor","orig":"An Act Converting the Land Transportation Office - Medellin Extension Office Into a Regular District Office and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11152","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11152_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9597-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Land Transportation Office - Medellin Extension Office located in the Municipality of Medellin, Province of Cebu is hereby converted into a regular Land Transportation Office (LTO) District Office."}},{"id":"PH-H9597-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation shall issue rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H9597-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Transportation shall immediately include in the Department’s programs the operationalization of a regular district office in the Municipality of Medellin, Province of Cebu, the initial funding of which shall be charged against the current year’s appropriations of the Land Transportation Office – Medellin Extension Office. Thereafter, such sums as may be necessary for the continued operation of the LTO District Office shall be included in the annual General Appropriations Act."}},{"id":"PH-H9597-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9598"] = {"id":"PH-H9598","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11153_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Panabo市","en":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Panabo, Province of Davao Del Norte and Appropriating Funds Therefor","orig":"An Act Establishing a Regular District Office of the Land Transportation Office (LTO) in the City of Panabo, Province of Davao Del Norte and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11153","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11153_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9598-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Transportation (DOTr), a regular district office of the Land Transportation Office (LTO) in the City of Panabo, Province of Davao del Norte, to be known as the \"Panabo City Land Transportation Regular District Office\"."}},{"id":"PH-H9598-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the DOTr shall immediately include in the Department’s programs the operationalization of the LTO regular district office in the City of Panabo, Province of Davao del Norte, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9598-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the DOTr shall issue the necessary rules and regulations within ninety (90) days from the effectivity of this Act."}},{"id":"PH-H9598-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9599"] = {"id":"PH-H9599","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11154_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Establishing a Land Transportation Office (LTO) Satellite Office in Ticao Island, Province of Masbate and Appropriating Funds Therefor","orig":"An Act Establishing a Land Transportation Office (LTO) Satellite Office in Ticao Island, Province of Masbate and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11154","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11154_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9599-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a Land Transportation Office (LTO) Satellite Office in Ticao Island, Province of Masbate to be known as the LTO Ticao Satellite Office."}},{"id":"PH-H9599-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation shall immediately include in the Department’s program the operationalization of the LTO Satellite Office in Ticao Island, Province of Masbate, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9599-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Transportation shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9599-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9600"] = {"id":"PH-H9600","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11155_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Valencia市","en":"An Act Establishing a Land Transportation Office (LTO) District Office in the City of Valencia, Province of Bukidnon and Appropriating Funds Therefor","orig":"An Act Establishing a Land Transportation Office (LTO) District Office in the City of Valencia, Province of Bukidnon and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11155","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11155_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9600-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a Land Transportation Office (LTO) District Office in the City of Valencia, Province of Bukidnon."}},{"id":"PH-H9600-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Transportation shall immediately include in the D epartment’s program the operationalization of the LTO District Office in the City of Valencia, Province of Bukidnon, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9600-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Transportation shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H9600-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9601"] = {"id":"PH-H9601","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11156_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sipalay市","en":"An Act Establishing a Land Transportation Office (LTO) District Office in the City of Sipalay, Province of Negros Occidental and Appropriating Funds Therefor","orig":"An Act Establishing a Land Transportation Office (LTO) District Office in the City of Sipalay, Province of Negros Occidental and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11156","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11156_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9601-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a district office of the Land Transportation Office (LTO) in the City of Sipalay, Province of Negros Occidental."}},{"id":"PH-H9601-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Transportation (DOTr) shall immediately include in the Department’s programs the operationalization of the LTO District Office in the City of Sipalay, Province of Negros Occidental, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9601-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the DOTr shall issue rules and regulations necessary for the effective implementation of this Act within sixty (60) days from the effectivity of this Act."}},{"id":"PH-H9601-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
