  FT["PH-H9604"] = {"id":"PH-H9604","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11159_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Philippine Citizenship to Mayleen Ting","orig":"An Act Granting Philippine Citizenship to Mayleen Ting"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11159","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11159_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9604-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Ms. Mayleen Ting is hereby granted Philippine citizenship with all the rights, privileges and prerogatives, as well as the duties and obligations appurtenant thereto."}},{"id":"PH-H9604-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Ms. Mayleen Ting shall take the Oath of Allegiance to the Republic of the Philippines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H9604-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Ms. Mayleen Ting who shall thereupon enter into the full enjoyment of Philippine citizenship."}},{"id":"PH-H9604-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
  FT["PH-H9605"] = {"id":"PH-H9605","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2018/ra_11160_2018.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting Philippine Citizenship to Father Julian C. Mazana","orig":"An Act Granting Philippine Citizenship to Father Julian C. Mazana"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11160","issuingBody":"Congress of the Philippines","promulgatedDate":"2018-12-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2018/ra_11160_2018.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9605-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Fr. Julian C. Mazana is hereby granted Philippine citizenship with all the rights, privileges and prerogatives, as well as the duties and obligations appurtenant thereto."}},{"id":"PH-H9605-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Fr. Julian C. Mazana shall take the Oath of Allegiance to the Republic of the Philippines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H9605-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Fr. Julian C. Mazana who shall thereupon enter into the full enjoyment of Philippine citizenship."}},{"id":"PH-H9605-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p136"};
